EOF
cat > src/main.rs <<'EOF'
use std::cmp::Ordering;
#[derive(Clone, Debug)]
struct Rec { a: Option<i64>, name: String }
fn run(data: &str, desc: bool, stable: bool, err_ord: Ordering) -> String {
    let mut v: Vec<Rec> = data.split(' ').map(|t| Rec { a: if t == "_" { None } else { Some(t.parse().unwrap()) }, name: t.to_string() }).collect();
    let cmp = |l: &Rec, r: &Rec| -> Ordering {
        match (l.a, r.a) {
            (Some(x), Some(y)) => if desc { y.cmp(&x) } else { x.cmp(&y) },
            _ => err_ord,
        }
    };
    if stable { v.sort_by(cmp); } else { v.sort_unstable_by(cmp); }
    v.iter().map(|r| r.name.clone()).collect::<Vec<_>>().join(" ")
}
fn main() {
    let cases = ["1 2 3 4 _ 10", "_ 1 2 3", "1 _ 2 3", "1 2 _ 3", "1 2 3 _", "_ _ 1 2", "1 _ _ 2", "3 1 _ 2", "_ 3 1 2", "1 _"];
    let expected_asc = ["_ 1 2 3 4 10", "_ 1 2 3", "1 2 3 _", "_ 1 2 3", "1 2 3 _", "1 2 _ _", "_ 1 2 _", "_ 1 2 3", "1 2 3 _", "1 _"];
    let expected_desc = ["_ 10 4 3 2 1", "_ 3 2 1", "3 2 1 _", "_ 3 2 1", "3 2 1 _", "2 1 _ _", "_ 2 1 _", "_ 3 2 1", "3 2 1 _", "1 _"];
    for stable in [true, false] {
        for err_ord in [Ordering::Less, Ordering::Equal, Ordering::Greater] {
            let mut ok = 0; let mut total = 0;
            for (i, c) in cases.iter().enumerate() {
                let a = run(c, false, stable, err_ord);
                let d = run(c, true, stable, err_ord);
                total += 2;
                if a == expected_asc[i] { ok += 1; }
                if d == expected_desc[i] { ok += 1; }
            }
            println!("stable={} err={:?}: {}/{}", stable, err_ord, ok, total);
        }
    }
}
EOF
cargo run --release --offline 2>&1 | tail -8"}

