    pub fn total_cmp(&self, other: &Value) -> Ordering {
        match self.compare(other) {
            Some(o) => o,
            None => match (self, other) {
                (Value::Array(a), Value::Array(b)) => {
                    for (x, y) in a.iter().zip(b.iter()) {
