impl Hash for Value {
    fn hash<H: Hasher>(&self, state: &mut H) {
        match self {
            Value::None => 0u8.hash(state),
            Value::Bool(b) => {
                1u8.hash(state);
                b.hash(state)
            }
            Value::Int(i) => {
                2u8.hash(state);
                (*i as f64).to_bits().hash(state)
            }
            Value::Float(f) => {
                2u8.hash(state);
                if f.fract() == 0.0 && f.is_finite() {
                    f.to_bits().hash(state)
                } else {
                    f.to_bits().hash(state)
                }
            }
