                3u8.hash(state);
                s.hash(state)
            }
            Value::Array(a) => {
                4u8.hash(state);
                a.hash(state)
            }
            Value::Obj(o) => {
                5u8.hash(state);
                for (k, v) in o {
                    k.hash(state);
                    v.hash(state);
                }
            }
            Value::DateTime(d) => {
                6u8.hash(state);
                d.hash(state)
            }
            Value::Duration(d) => {
                7u8.hash(state);
                d.hash(state)
            }
        }
    }
