pub fn format_duration(d: &TimeDelta) -> String {
    // components: w d h m s ms us (no ns); negative durations get a sign on every component
    let neg = *d < TimeDelta::zero();
    let abs = if neg { -*d } else { *d };
    let total_us = abs.num_microseconds().unwrap_or(0);
    let mut rem = total_us;
    let units: [(&str, i64); 7] = [
        ("w", 7 * 24 * 3600 * 1_000_000),
        ("d", 24 * 3600 * 1_000_000),
        ("h", 3600 * 1_000_000),
        ("m", 60 * 1_000_000),
        ("s", 1_000_000),
        ("ms", 1000),
        ("us", 1),
    ];
    let mut out = String::new();
    for (name, size) in units.iter() {
        let n = rem / size;
        rem %= size;
        if n != 0 {
            if neg {
                out.push('-');
            }
            out.push_str(&n.to_string());
            out.push_str(name);
        }
    }
    out
}

impl fmt::Display for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Value::None => write!(f, "None"),
            Value::Bool(b) => write!(f, "{}", b),
            Value::Int(i) => write!(f, "{}", i),
            Value::Float(x) => write!(f, "{:.2}", x),
            Value::Str(s) => write!(f, "{}", s),
            Value::Array(a) => {
                write!(f, "[")?;
                for (i, v) in a.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}", v)?;
                }
                write!(f, "]")
            }
            Value::Obj(o) => {
                write!(f, "{{")?;
                for (i, (k, v)) in o.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{}:{}", k, v)?;
                }
                write!(f, "}}")
            }
            Value::DateTime(d) => write!(f, "{}", d),
            Value::Duration(d) => write!(f, "{}", format_duration(d)),
        }
    }
}

impl fmt::Debug for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Value::None => write!(f, "None"),
            Value::Bool(b) => write!(f, "Bool({:?})", b),
            Value::Int(i) => write!(f, "Int({:?})", i),
            Value::Float(x) => write!(f, "Float({:?})", x),
            Value::Str(s) => write!(f, "Str({:?})", s),
            Value::Array(a) => write!(f, "Array({:?})", a),
            Value::Obj(o) => write!(f, "Obj({:?})", o),
            Value::DateTime(d) => write!(f, "DateTime({:?})", d),
            Value::Duration(d) => write!(f, "Duration({:?})", d),
        }
    }
}
