                            a[idx as usize].clone()
                        }
                        (PathElem::Index(_), other) => return Err(format!("Expected array, found {}", other)),
                    };
                }
                Ok(cur)
            }
            Expr::Not(e) => match e.eval(rec)? {
                Value::Bool(b) => Ok(Value::Bool(!b)),
                other => Err(format!("Expected boolean, found {}", other)),
            },
            Expr::Binary { op, l, r } => eval_binary(op, l, r, rec),
            Expr::If { cond, then, els } => match cond.eval(rec)? {
                Value::Bool(true) => then.eval(rec),
                Value::Bool(false) => els.eval(rec),
                other => Err(format!("Expected boolean, found {}", other)),
            },
            Expr::Call { name, args } => eval_call(name, args, rec),
        }
    }
}

fn expect_bool(v: Value) -> Result<bool, String> {
    match v {
        Value::Bool(b) => Ok(b),
        other => Err(format!("Expected boolean, found {}", other)),
    }
}

fn eval_binary(op: &BinOp, l: &Expr, r: &Expr, rec: &Record) -> EvalResult {
    match op {
        BinOp::And => {
            let lv = expect_bool(l.eval(rec)?)?;
            if !lv {
                return Ok(Value::Bool(false));
            }
            let rv = expect_bool(r.eval(rec)?)?;
            Ok(Value::Bool(rv))
        }
        BinOp::Or => {
            let lv = expect_bool(l.eval(rec)?)?;
            if lv {
                return Ok(Value::Bool(true));
            }
            let rv = expect_bool(r.eval(rec)?)?;
            Ok(Value::Bool(rv))
        }
        BinOp::Eq => {
            let lv = l.eval(rec)?;
            let rv = r.eval(rec)?;
            Ok(Value::Bool(lv == rv))
        }
        BinOp::Ne => {
            let lv = l.eval(rec)?;
            let rv = r.eval(rec)?;
            Ok(Value::Bool(lv != rv))
        }
        BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge => {
            let lv = l.eval(rec)?;
            let rv = r.eval(rec)?;
            let res = match lv.compare(&rv) {
                None => false,
                Some(o) => match op {
                    BinOp::Lt => o == std::cmp::Ordering::Less,
                    BinOp::Le => o != std::cmp::Ordering::Greater,
                    BinOp::Gt => o == std::cmp::Ordering::Greater,
                    BinOp::Ge => o != std::cmp::Ordering::Less,
                    _ => unreachable!(),
                },
            };
            Ok(Value::Bool(res))
        }
        BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div => {
            let lv = l.eval(rec)?;
            let rv = r.eval(rec)?;
            arith(op, lv, rv)
        }
    }
}

fn op_sym(op: &BinOp) -> &'static str {
    match op {
        BinOp::Add => "+",
        BinOp::Sub => "-",
        BinOp::Mul => "*",
        BinOp::Div => "/",
        _ => "?",
    }
}

fn dt_millis(dt: &chrono::DateTime<Utc>) -> i64 {
    dt.timestamp_millis()
}

pub fn arith(op: &BinOp, lv: Value, rv: Value) -> EvalResult {
    // date-time / duration arithmetic
    match (&lv, &rv) {
        (Value::DateTime(a), Value::DateTime(b)) => match op {
            BinOp::Sub => return Ok(Value::Duration(*a - *b)),
            _ => {
                return arith(op, Value::Int(dt_millis(a)), Value::Int(dt_millis(b)));
            }
        },
        (Value::DateTime(a), Value::Duration(d)) => match op {
            BinOp::Add => return Ok(Value::DateTime(*a + *d)),
            BinOp::Sub => return Ok(Value::DateTime(*a - *d)),
            _ => {}
        },
        (Value::Duration(d), Value::DateTime(a)) => {
            if let BinOp::Add = op {
                return Ok(Value::DateTime(*a + *d));
            }
        }
        (Value::Duration(a), Value::Duration(b)) => match op {
            BinOp::Add => return Ok(Value::Duration(*a + *b)),
            BinOp::Sub => return Ok(Value::Duration(*a - *b)),
            _ => {}
        },
        (Value::Duration(d), Value::Int(i)) => match op {
            BinOp::Mul => return Ok(Value::Duration(*d * (*i as i32))),
            BinOp::Div => {
                if *i != 0 {
                    return Ok(Value::Duration(*d / (*i as i32)));
                }
            }
            _ => {}
        },
        (Value::Duration(d), Value::Float(f)) => match op {
            BinOp::Mul | BinOp::Div => {
                let nanos = d.num_nanoseconds().unwrap_or(0) as f64;
                let res = if let BinOp::Mul = op { nanos * f } else { nanos / f };
                return Ok(Value::Duration(TimeDelta::nanoseconds(res as i64)));
            }
            _ => {}
        },
        (Value::DateTime(a), _) => {
            if rv.to_number().is_some() {
                return arith(op, Value::Int(dt_millis(a)), rv);
            }
        }
        (_, Value::DateTime(b)) => {
            if lv.to_number().is_some() {
                return arith(op, lv, Value::Int(dt_millis(b)));
            }
        }
        _ => {}
    }
    let has_str = matches!(lv, Value::Str(_)) || matches!(rv, Value::Str(_));
    let ln = lv.to_number();
    let rn = rv.to_number();
    let (ln, rn) = match (ln, rn) {
        (Some(a), Some(b)) => (a, b),
        _ => {
            return Err(format!(
                "Expected numeric operands, found {} {} {}",
                lv.to_string_lossy(),
                op_sym(op),
                rv.to_string_lossy()
            ))
        }
    };
    let as_f = |v: &Value| match v {
        Value::Int(i) => *i as f64,
        Value::Float(f) => *f,
        _ => 0.0,
    };
    if has_str {
        let (a, b) = (as_f(&ln), as_f(&rn));
        let res = match op {
            BinOp::Add => a + b,
            BinOp::Sub => a - b,
            BinOp::Mul => a * b,
            BinOp::Div => a / b,
            _ => unreachable!(),
        };
        return Ok(Value::from_float(res));
    }
    match (&ln, &rn) {
        (Value::Int(a), Value::Int(b)) => match op {
            BinOp::Add => Ok(Value::Int(a.wrapping_add(*b))),
            BinOp::Sub => Ok(Value::Int(a.wrapping_sub(*b))),
            BinOp::Mul => Ok(Value::Int(a.wrapping_mul(*b))),
            BinOp::Div => Ok(Value::from_float(*a as f64 / *b as f64)),
            _ => unreachable!(),
        },
        _ => {
            let (a, b) = (as_f(&ln), as_f(&rn));
            match op {
                BinOp::Add => Ok(Value::Float(a + b)),
                BinOp::Sub => Ok(Value::Float(a - b)),
                BinOp::Mul => Ok(Value::from_float(a * b)),
                BinOp::Div => Ok(Value::from_float(a / b)),
                _ => unreachable!(),
            }
        }
    }
}

fn expect_number(v: &Value) -> Result<f64, String> {
    match v.to_f64() {
        Some(f) => Ok(f),
        None => Err(format!("Expected number, found {}", v.to_string_lossy())),
    }
}

fn arity(name: &str, args: &[Expr], n: usize) -> Result<(), String> {
    if args.len() != n {
        Err(format!("The '{}' function expects {} arguments, found {}", name, n, args.len()))
    } else {
        Ok(())
    }
}

fn eval_args(args: &[Expr], rec: &Record) -> Result<Vec<Value>, String> {
    args.iter().map(|a| a.eval(rec)).collect()
}

fn func_err(name: &str, msg: String) -> String {
    format!("The '{}' function failed with the error: {}", name, msg)
}

fn offset_arg(v: &Value) -> Result<usize, String> {
    match v {
        Value::Int(i) if *i >= 0 => Ok(*i as usize),
        Value::Float(f) if *f >= 0.0 => Ok(*f as usize),
        Value::Str(s) => match Value::from_string(s) {
            Value::Int(i) if i >= 0 => Ok(i as usize),
            Value::Float(f) if f >= 0.0 => Ok(f as usize),
            _ => Err(format!("Expected positive number, found {}", v.to_string_lossy())),
        },
        _ => Err(format!("Expected positive number, found {}", v.to_string_lossy())),
    }
}

fn eval_call(name: &str, args: &[Expr], rec: &Record) -> EvalResult {
    if MATH1.contains(&name) {
        arity(name, args, 1)?;
        let v = args[0].eval(rec)?;
        let x = expect_number(&v)?;
        let res = match name {
            "abs" => x.abs(),
            "acos" => x.acos(),
            "asin" => x.asin(),
            "atan" => x.atan(),
            "cbrt" => x.cbrt(),
            "ceil" => x.ceil(),
            "cos" => x.cos(),
            "cosh" => x.cosh(),
            "exp" => x.exp(),
            "expm1" => x.exp_m1(),
            "floor" => x.floor(),
            "log" => x.ln(),
            "log10" => x.log10(),
            "log1p" => x.ln_1p(),
            "round" => x.round(),
            "sin" => x.sin(),
            "sinh" => x.sinh(),
            "sqrt" => x.sqrt(),
            "tan" => x.tan(),
            "tanh" => x.tanh(),
            "toDegrees" => x.to_degrees(),
            "toRadians" => x.to_radians(),
            _ => unreachable!(),
        };
        return Ok(Value::from_float(res));
    }
    match name {
        "atan2" | "hypot" => {
            arity(name, args, 2)?;
            let a = expect_number(&args[0].eval(rec)?)?;
            let b = expect_number(&args[1].eval(rec)?)?;
            let res = if name == "atan2" { a.atan2(b) } else { a.hypot(b) };
            Ok(Value::from_float(res))
        }
        "concat" => {
            let vals = eval_args(args, rec)?;
            let mut s = String::new();
            for v in vals {
                s.push_str(&v.to_string_lossy());
            }
            Ok(Value::Str(s))
        }
        "contains" => {
            arity(name, args, 2)?;
            let h = args[0].eval(rec)?.to_string_lossy();
            let n = args[1].eval(rec)?.to_string_lossy();
            Ok(Value::Bool(h.contains(&n)))
        }
        "length" => {
            arity(name, args, 1)?;
            let v = args[0].eval(rec)?;
            let n = match &v {
                Value::Array(a) => a.len(),
                Value::Obj(o) => o.len(),
                other => other.to_string_lossy().chars().count(),
            };
            Ok(Value::Int(n as i64))
        }
        "now" => {
            arity(name, args, 0)?;
            Ok(Value::DateTime(Utc::now()))
        }
        "num" => {
            arity(name, args, 1)?;
            let v = args[0].eval(rec)?;
            match &v {
                Value::DateTime(d) => Ok(Value::Int(d.timestamp_millis())),
                _ => match v.to_number() {
                    Some(n) => Ok(n),
                    None => Err(format!("Expected number, found {}", v.to_string_lossy())),
                },
            }
        }
        "parseDate" => {
            arity(name, args, 1)?;
            let v = args[0].eval(rec)?;
            match &v {
                Value::Str(s) => match dateparse::parse(s) {
                    Ok(dt) => Ok(Value::DateTime(dt)),
                    Err(e) => Err(func_err(name, e)),
                },
                Value::DateTime(_) => Ok(v),
                _ => Err(func_err(name, "NoDate".to_string())),
            }
        }
        "parseHex" => {
            arity(name, args, 1)?;
            let v = args[0].eval(rec)?;
            let s = v.to_string_lossy();
            let t = s.trim();
            let digits = t.strip_prefix("0x").unwrap_or(t);
            match i64::from_str_radix(digits, 16) {
                Ok(i) if !digits.is_empty() && !digits.starts_with('+') => Ok(Value::Int(i)),
                _ => Err(func_err(name, format!("invalid hex string -- {}", s))),
            }
        }
        "substring" => {
            if args.len() != 2 && args.len() != 3 {
                return Err(format!("The '{}' function expects 2 arguments, found {}", name, args.len()));
            }
            let s = args[0].eval(rec)?.to_string_lossy();
            let start = offset_arg(&args[1].eval(rec)?)?;
            let chars: Vec<char> = s.chars().collect();
            let end = if args.len() == 3 { Some(offset_arg(&args[2].eval(rec)?)?) } else { None };
            if let Some(e) = end {
                if e < start {
                    return Err(func_err(
                        name,
                        format!("end offset ({}) is less than the start offset ({})", e, start),
                    ));
                }
            }
            let st = start.min(chars.len());
            let en = end.map(|e| e.min(chars.len())).unwrap_or(chars.len());
            Ok(Value::Str(chars[st..en.max(st)].iter().collect()))
        }
        "toLowerCase" => {
            arity(name, args, 1)?;
            let s = args[0].eval(rec)?.to_string_lossy();
            Ok(Value::from_string(&s.to_lowercase()))
        }
        "toUpperCase" => {
            arity(name, args, 1)?;
            let s = args[0].eval(rec)?.to_string_lossy();
            Ok(Value::from_string(&s.to_uppercase()))
        }
        "isNull" => {
            arity(name, args, 1)?;
            Ok(Value::Bool(matches!(args[0].eval(rec)?, Value::None)))
        }
        "isEmpty" => {
            arity(name, args, 1)?;
            let v = args[0].eval(rec)?;
            Ok(Value::Bool(match &v {
                Value::None => true,
                Value::Str(s) => s.is_empty(),
                _ => false,
            }))
        }
        "isBlank" => {
            arity(name, args, 1)?;
            let v = args[0].eval(rec)?;
            Ok(Value::Bool(match &v {
                Value::None => true,
                Value::Str(s) => s.trim().is_empty(),
                _ => false,
            }))
        }
        "isNumeric" => {
            arity(name, args, 1)?;
            let v = args[0].eval(rec)?;
            Ok(Value::Bool(match &v {
                Value::DateTime(_) => true,
                _ => v.to_number().is_some(),
            }))
        }
        _ => Err(format!("Unknown function {}", name)),
    }
}

pub fn empty_obj() -> BTreeMap<String, Value> {
    BTreeMap::new()
}
