//! CKMS streaming quantile estimator (compatible with the `quantiles` crate behaviour).

#[derive(Clone, Debug)]
struct Entry {
    v: f64,
    g: usize,
    delta: usize,
}

#[derive(Clone, Debug)]
pub struct Ckms {
    n: usize,
    error: f64,
    insert_threshold: usize,
    inserts: usize,
    samples: Vec<Entry>,
}

impl Ckms {
    pub fn new(error: f64) -> Ckms {
        let t = 1.0 / (2.0 * error);
        let insert_threshold = if t < 1.0 { 1 } else { t as usize };
        Ckms { n: 0, error, insert_threshold, inserts: 0, samples: Vec::new() }
    }

    fn invariant(&self, r: f64) -> usize {
        let i = (2.0 * self.error * r).floor() as usize;
        if i < 1 {
            1
        } else {
            i
        }
    }

    pub fn insert(&mut self, v: f64) {
        self.n += 1;
        let s = self.samples.len();
        if s == 0 {
            self.samples.push(Entry { v, g: 1, delta: 0 });
        } else {
            let mut idx = 0;
            let mut r = 0usize;
            for e in self.samples.iter() {
                if e.v < v {
                    idx += 1;
                    r += e.g;
                } else {
                    break;
                }
            }
            let delta = if idx == 0 || idx == s { 0 } else { self.invariant(r as f64) - 1 };
            self.samples.insert(idx, Entry { v, g: 1, delta });
        }
        self.inserts = (self.inserts + 1) % self.insert_threshold;
        if self.inserts == 0 {
            self.compress();
        }
    }

    fn compress(&mut self) {
        if self.samples.len() < 3 {
            return;
        }
        let mut s_mx = self.samples.len() - 1;
        let mut idx = 0;
        let mut r: usize = 1;
        while idx < s_mx {
            let cur_g = self.samples[idx].g;
            let nxt_v = self.samples[idx + 1].v;
            let nxt_g = self.samples[idx + 1].g;
            let nxt_delta = self.samples[idx + 1].delta;
            if cur_g + nxt_g + nxt_delta <= self.invariant(r as f64) {
                self.samples[idx].v = nxt_v;
                self.samples[idx].g += nxt_g;
                self.samples[idx].delta = nxt_delta;
                self.samples.remove(idx + 1);
                s_mx -= 1;
            } else {
                idx += 1;
            }
            r += 1;
        }
    }

    pub fn query(&self, q: f64) -> Option<f64> {
        let s = self.samples.len();
        if s == 0 {
            return None;
        }
        let mut r = 0usize;
        let nphi = q * (self.n as f64);
        for i in 1..s {
            let prev = &self.samples[i - 1];
            let cur = &self.samples[i];
            r += prev.g;
            let lhs = (r + cur.g + cur.delta) as f64;
            let rhs = nphi + (self.invariant(nphi) as f64) / 2.0;
            if lhs > rhs {
                return Some(prev.v);
            }
        }
        Some(self.samples[s - 1].v)
    }
}
