//! A logfmt parser replicating the quirks of the original implementation.

#[derive(PartialEq)]
enum State {
    Garbage,
    Key,
    Value,
    Skip,
}

pub fn parse(line: &str) -> Vec<(String, Option<String>)> {
    let mut pairs: Vec<(String, Option<String>)> = Vec::new();
    let mut key = String::new();
    let mut value = String::new();
    let mut state = State::Key; // initial state acts like an (empty) key
    let mut in_quotes = false;
    let mut escaped = false;

    let mut emit = |pairs: &mut Vec<(String, Option<String>)>, k: &str, v: Option<String>| {
        pairs.push((k.to_string(), v));
    };

    for c in line.chars() {
        match state {
            State::Garbage => {
                if c == ' ' {
                    // stay
                } else if c == '"' {
                    key.clear();
                    in_quotes = true;
                    state = State::Key;
                } else if c == '=' {
                    state = State::Skip;
                } else {
                    key.clear();
                    key.push(c);
                    state = State::Key;
                }
            }
            State::Skip => {
                if c == ' ' {
                    state = State::Garbage;
                }
            }
            State::Key => {
                if in_quotes {
                    if c == '"' {
                        in_quotes = false;
                    } else {
                        key.push(c);
                    }
                } else if c == '"' {
                    in_quotes = true;
                } else if c == '=' {
                    if key.is_empty() {
                        state = State::Skip;
                    } else {
                        value.clear();
                        state = State::Value;
                    }
                } else if c == ' ' {
                    if !key.is_empty() {
                        emit(&mut pairs, &key, None);
                        key.clear();
                        state = State::Garbage;
                    }
                } else {
                    key.push(c);
                }
            }
            State::Value => {
                if in_quotes {
                    if escaped {
                        if c == '"' {
                            value.push('"');
                        } else if c == '\\' {
                            // stay escaped
                            continue;
                        } else {
                            value.push('\\');
                            value.push(c);
                        }
                        escaped = false;
                    } else if c == '\\' {
                        escaped = true;
                    } else if c == '"' {
                        in_quotes = false;
                    } else {
                        value.push(c);
                    }
                } else if c == '"' {
                    in_quotes = true;
                    escaped = false;
                } else if c == '=' {
                    key = std::mem::take(&mut value);
                    value.clear();
                } else if c == ' ' {
                    if !value.is_empty() {
                        if !key.is_empty() {
                            emit(&mut pairs, &key, Some(std::mem::take(&mut value)));
                        }
                        key.clear();
                        value.clear();
                        state = State::Garbage;
                    }
                } else {
                    value.push(c);
                }
            }
        }
    }
    match state {
        State::Key => emit(&mut pairs, &key, None),
        State::Value => {
            if !key.is_empty() {
                emit(&mut pairs, &key, Some(value));
            }
        }
        _ => {}
    }
    pairs
}
