use crate::ckms::Ckms;
use crate::expr::Expr;
use crate::logfmt;
use crate::record::Record;
use crate::value::Value;
use chrono::{DurationRound, TimeDelta};
use regex::Regex;
use std::collections::{BTreeMap, HashMap, HashSet};

#[derive(Clone, Debug, PartialEq)]
pub enum FieldMode {
    Only,
    Except,
}

#[derive(Clone, Debug)]
pub enum InlineOp {
    Json { from: Option<Expr> },
    Logfmt { from: Option<Expr> },
    Parse { regex: Regex, fields: Vec<String>, from: Option<Expr>, nodrop: bool, noconvert: bool },
    ParseRegex { regex: Regex, from: Option<Expr>, nodrop: bool, noconvert: bool },
    Split { input: Option<Expr>, sep: String, output: Option<Expr> },
    Fields { mode: FieldMode, names: Vec<String> },
    Where(Option<Expr>),
    Limit(Option<i64>),
    Total { expr: Expr, name: String },
    Timeslice { expr: Expr, duration: Option<TimeDelta>, name: String },
    FieldExpr { expr: Expr, name: String },
    NoOp,
}

#[derive(Clone, Debug)]
pub enum AggFunc {
    Count(Option<Expr>),
    Sum(Expr),
    Min(Expr),
    Max(Expr),
    Avg(Expr),
    Percentile(Expr, f64),
    CountDistinct(Expr),
}

#[derive(Clone, Debug)]
pub struct MultiAgg {
    pub aggs: Vec<(AggFunc, String)>,
    pub keys: Vec<(Expr, String)>,
}

#[derive(Clone, Debug)]
pub struct SortOp {
    pub exprs: Vec<Expr>,
    pub desc: bool,
}

#[derive(Clone, Debug)]
pub enum Operator {
    Inline(InlineOp),
    Agg(MultiAgg),
    Sort(SortOp),
}

pub fn report(msg: &str) {
    eprintln!("error: {}", msg);
}

// ---------------------------------------------------------------------------
// Inline operator execution

pub struct InlineState {
    pub op: InlineOp,
    count: i64,
    buffer: Vec<Record>,
    total: f64,
}

impl InlineState {
    pub fn new(op: InlineOp) -> InlineState {
        InlineState { op, count: 0, buffer: Vec::new(), total: 0.0 }
    }

    pub fn reset(&mut self) {
        self.count = 0;
        self.buffer.clear();
        self.total = 0.0;
    }

    /// Returns true if this operator is still accepting input (false once a positive limit was reached).
    pub fn accepting(&self) -> bool {
        match &self.op {
            InlineOp::Limit(Some(n)) if *n > 0 => self.count < *n,
            _ => true,
        }
    }

    pub fn process(&mut self, mut rec: Record) -> Option<Record> {
        match &self.op {
            InlineOp::NoOp => Some(rec),
            InlineOp::Json { from } => {
                let text = match from {
                    None => rec.raw.clone(),
                    Some(e) => match e.eval(&rec) {
                        Ok(Value::Str(s)) => s,
                        Ok(_) => {
                            report("Expected string, found other");
                            return None;
                        }
                        Err(e) => {
                            report(&e);
                            return None;
                        }
                    },
                };
                match serde_json::from_str::<serde_json::Value>(&text) {
                    Ok(serde_json::Value::Object(o)) => {
                        for (k, v) in o {
                            rec.fields.insert(k, Value::from_json(v));
                        }
                        Some(rec)
                    }
                    Ok(_) => Some(rec),
                    Err(_) => {
                        report(&format!("Expected JSON, found {}", text));
                        None
                    }
                }
            }
            InlineOp::Logfmt { from } => {
                let text = match from {
                    None => rec.raw.clone(),
                    Some(e) => match e.eval(&rec) {
                        Ok(Value::Str(s)) => s,
                        Ok(_) => {
                            report("Expected string, found other");
                            return None;
                        }
                        Err(e) => {
                            report(&e);
                            return None;
                        }
                    },
                };
                for (k, v) in logfmt::parse(&text) {
                    let val = match v {
                        None => Value::None,
                        Some(s) => Value::from_string(&s),
                    };
                    rec.fields.insert(k, val);
                }
                Some(rec)
            }
            InlineOp::Parse { regex, fields, from, nodrop, noconvert } => {
                let text = match from {
                    None => rec.raw.clone(),
                    Some(e) => match e.eval(&rec) {
                        Ok(Value::Str(s)) => s,
                        Ok(_) => {
                            report("Expected string, found other");
                            return None;
                        }
                        Err(e) => {
                            report(&e);
                            return None;
                        }
                    },
                };
                match regex.captures(&text) {
                    Some(caps) => {
                        for (i, name) in fields.iter().enumerate() {
                            let s = caps.get(i + 1).map(|m| m.as_str()).unwrap_or("");
                            let v = if *noconvert { Value::Str(s.to_string()) } else { Value::from_string(s) };
                            rec.fields.insert(name.clone(), v);
                        }
                        Some(rec)
                    }
                    None => {
                        if *nodrop {
                            for name in fields {
                                rec.fields.insert(name.clone(), Value::None);
                            }
                            Some(rec)
                        } else {
                            None
                        }
                    }
                }
            }
            InlineOp::ParseRegex { regex, from, nodrop, noconvert } => {
                let text = match from {
                    None => rec.raw.clone(),
                    Some(e) => match e.eval(&rec) {
                        Ok(Value::Str(s)) => s,
                        Ok(_) => {
                            report("Expected string, found other");
                            return None;
                        }
                        Err(e) => {
                            report(&e);
                            return None;
                        }
                    },
                };
                let names: Vec<&str> = regex.capture_names().flatten().collect();
                match regex.captures(&text) {
                    Some(caps) => {
                        for name in names {
                            let v = match caps.name(name) {
                                Some(m) => {
                                    if *noconvert {
                                        Value::Str(m.as_str().to_string())
                                    } else {
                                        Value::from_string(m.as_str())
                                    }
                                }
                                None => Value::None,
                            };
                            rec.fields.insert(name.to_string(), v);
                        }
                        Some(rec)
                    }
                    None => {
                        if *nodrop {
                            for name in names {
                                rec.fields.insert(name.to_string(), Value::None);
                            }
                            Some(rec)
                        } else {
                            None
                        }
                    }
                }
            }
            InlineOp::Split { input, sep, output } => {
                let (text, in_col) = match input {
                    None => (rec.raw.clone(), None),
                    Some(e) => {
                        let col = match e.is_column() {
                            Some(c) => c.to_string(),
                            None => {
                                report("Expected valid expr, found value expr");
                                return None;
                            }
                        };
                        match e.eval(&rec) {
                            Ok(Value::Str(s)) => (s, Some(col)),
                            Ok(_) => {
                                report("Expected string, found other");
                                return None;
                            }
                            Err(e) => {
                                report(&e);
                                return None;
                            }
                        }
                    }
                };
                let out_col = match output {
                    Some(e) => match e.is_column() {
                        Some(c) => c.to_string(),
                        None => {
                            report("Expected valid expr, found value expr");
                            return None;
                        }
                    },
                    None => in_col.unwrap_or_else(|| "_split".to_string()),
                };
                let parts: Vec<Value> = if sep.is_empty() {
                    text.chars().map(|c| Value::from_string(&c.to_string())).collect()
                } else {
                    text.split(sep.as_str()).filter(|s| !s.is_empty()).map(Value::from_string).collect()
                };
                rec.fields.insert(out_col, Value::Array(parts));
                Some(rec)
            }
            InlineOp::Fields { mode, names } => {
                match mode {
                    FieldMode::Only => {
                        rec.fields.retain(|k, _| names.contains(k));
                    }
                    FieldMode::Except => {
                        rec.fields.retain(|k, _| !names.contains(k));
                    }
                }
                if rec.fields.is_empty() {
                    None
                } else {
                    Some(rec)
                }
            }
            InlineOp::Where(None) => Some(rec),
            InlineOp::Where(Some(e)) => match e.eval(&rec) {
                Ok(Value::Bool(true)) => Some(rec),
                Ok(Value::Bool(false)) => None,
                Ok(other) => {
                    report(&format!("Expected boolean, found {}", other));
                    None
                }
                Err(e) => {
                    report(&e);
                    None
                }
            },
            InlineOp::Limit(None) => Some(rec),
            InlineOp::Limit(Some(n)) => {
                if *n > 0 {
                    if self.count < *n {
                        self.count += 1;
                        Some(rec)
                    } else {
                        None
                    }
                } else {
                    let keep = (-*n) as usize;
                    self.buffer.push(rec);
                    if self.buffer.len() > keep {
                        self.buffer.remove(0);
                    }
                    None
                }
            }
            InlineOp::Total { expr, name } => {
                match expr.eval(&rec) {
                    Ok(v) => {
                        if let Some(f) = v.to_f64() {
                            self.total += f;
                        }
                    }
                    Err(_) => {}
                }
                rec.fields.insert(name.clone(), Value::from_float(self.total));
                Some(rec)
            }
            InlineOp::Timeslice { expr, duration, name } => {
                let v = match expr.eval(&rec) {
                    Ok(v) => v,
                    Err(e) => {
                        report(&e);
                        return None;
                    }
                };
                let dt = match v {
                    Value::DateTime(dt) => dt,
                    other => {
                        report(&format!(
                            "Expected date, found '{}'.  Use parseDate() to convert a value to a date",
                            other
                        ));
                        return None;
                    }
                };
                let dur = duration.unwrap_or_else(|| TimeDelta::seconds(1));
                match dt.duration_trunc(dur) {
                    Ok(t) => {
                        rec.fields.insert(name.clone(), Value::DateTime(t));
                        Some(rec)
                    }
                    Err(e) => {
                        report(&format!("Duration is not valid for timeslice: {:?}", e));
                        None
                    }
                }
            }
            InlineOp::FieldExpr { expr, name } => match expr.eval(&rec) {
                Ok(v) => {
                    rec.fields.insert(name.clone(), v);
                    Some(rec)
                }
                Err(e) => {
                    report(&e);
                    None
                }
            },
        }
    }

    pub fn finish(&mut self) -> Vec<Record> {
        match &self.op {
            InlineOp::Limit(Some(n)) if *n < 0 => std::mem::take(&mut self.buffer),
            _ => Vec::new(),
        }
    }
}

// ---------------------------------------------------------------------------
// Aggregates

pub type Row = HashMap<String, Value>;

#[derive(Clone, Debug, Default)]
pub struct Table {
    pub columns: Vec<String>,
    pub rows: Vec<Row>,
}

impl Table {
    pub fn get<'a>(row: &'a Row, col: &str) -> Value {
        row.get(col).cloned().unwrap_or(Value::None)
    }
    pub fn row_to_record(row: &Row) -> Record {
        let mut fields = BTreeMap::new();
        for (k, v) in row {
            fields.insert(k.clone(), v.clone());
        }
        Record::from_fields(fields)
    }
}

enum AggState {
    Count(i64),
    Sum(f64),
    Min(Option<Value>),
    Max(Option<Value>),
    Avg(f64, i64),
    Percentile(Ckms),
    CountDistinct(HashSet<Value>),
}

impl AggState {
    fn new(f: &AggFunc) -> AggState {
        match f {
            AggFunc::Count(_) => AggState::Count(0),
            AggFunc::Sum(_) => AggState::Sum(0.0),
            AggFunc::Min(_) => AggState::Min(None),
            AggFunc::Max(_) => AggState::Max(None),
            AggFunc::Avg(_) => AggState::Avg(0.0, 0),
            AggFunc::Percentile(_, _) => AggState::Percentile(Ckms::new(0.001)),
            AggFunc::CountDistinct(_) => AggState::CountDistinct(HashSet::new()),
        }
    }

    fn process(&mut self, f: &AggFunc, rec: &Record) {
        match (self, f) {
            (AggState::Count(c), AggFunc::Count(None)) => *c += 1,
            (AggState::Count(c), AggFunc::Count(Some(e))) => {
                if let Ok(Value::Bool(true)) = e.eval(rec) {
                    *c += 1;
                }
            }
            (AggState::Sum(s), AggFunc::Sum(e)) => {
                if let Ok(v) = e.eval(rec) {
                    if let Some(f) = v.to_f64() {
                        *s += f;
                    }
                }
            }
            (AggState::Min(m), AggFunc::Min(e)) => {
                if let Ok(v) = e.eval(rec) {
                    if let Some(n) = v.to_number() {
                        let replace = match m {
                            None => true,
                            Some(cur) => n.total_cmp(cur) == std::cmp::Ordering::Less,
                        };
                        if replace {
                            *m = Some(n);
                        }
                    }
                }
            }
            (AggState::Max(m), AggFunc::Max(e)) => {
                if let Ok(v) = e.eval(rec) {
                    if let Some(n) = v.to_number() {
                        let replace = match m {
                            None => true,
                            Some(cur) => n.total_cmp(cur) == std::cmp::Ordering::Greater,
                        };
                        if replace {
                            *m = Some(n);
                        }
                    }
                }
            }
            (AggState::Avg(s, c), AggFunc::Avg(e)) => {
                if let Ok(v) = e.eval(rec) {
                    if let Some(f) = v.to_f64() {
                        *s += f;
                        *c += 1;
                    }
                }
            }
            (AggState::Percentile(ck), AggFunc::Percentile(e, _)) => {
                if let Ok(v) = e.eval(rec) {
                    if let Some(f) = v.to_f64() {
                        ck.insert(f);
                    }
                }
            }
            (AggState::CountDistinct(set), AggFunc::CountDistinct(e)) => {
                if let Ok(v) = e.eval(rec) {
                    set.insert(v);
                }
            }
            _ => {}
        }
    }

    fn emit(&self, f: &AggFunc) -> Value {
        match self {
            AggState::Count(c) => Value::Int(*c),
            AggState::Sum(s) => Value::from_float(*s),
            AggState::Min(m) | AggState::Max(m) => m.clone().unwrap_or(Value::None),
            AggState::Avg(s, c) => Value::from_float(*s / (*c as f64)),
            AggState::Percentile(ck) => {
                let p = match f {
                    AggFunc::Percentile(_, p) => *p,
                    _ => 50.0,
                };
                match ck.query(p / 100.0) {
                    Some(v) => Value::from_float(v),
                    None => Value::None,
                }
            }
            AggState::CountDistinct(set) => Value::Int(set.len() as i64),
        }
    }
}

pub struct MultiAggState {
    pub op: MultiAgg,
    groups: HashMap<Vec<Value>, Vec<AggState>>,
}

impl MultiAggState {
    pub fn new(op: MultiAgg) -> MultiAggState {
        MultiAggState { op, groups: HashMap::new() }
    }

    pub fn reset(&mut self) {
        self.groups.clear();
    }

    pub fn process(&mut self, rec: &Record) {
        let key: Vec<Value> = self
            .op
            .keys
            .iter()
            .map(|(e, _)| e.eval(rec).unwrap_or(Value::None))
            .collect();
        let aggs = &self.op.aggs;
        let states = self
            .groups
            .entry(key)
            .or_insert_with(|| aggs.iter().map(|(f, _)| AggState::new(f)).collect());
        for (st, (f, _)) in states.iter_mut().zip(aggs.iter()) {
            st.process(f, rec);
        }
    }

    pub fn emit(&self) -> Table {
        let mut columns: Vec<String> = self.op.keys.iter().map(|(_, n)| n.clone()).collect();
        for (_, n) in &self.op.aggs {
            columns.push(n.clone());
        }
        let mut rows: Vec<(Vec<Value>, Vec<Value>)> = self
            .groups
            .iter()
            .map(|(k, states)| {
                let vals: Vec<Value> =
                    states.iter().zip(self.op.aggs.iter()).map(|(s, (f, _))| s.emit(f)).collect();
                (k.clone(), vals)
            })
            .collect();
        rows.sort_by(|(ka, va), (kb, vb)| {
            for (x, y) in va.iter().zip(vb.iter()) {
                let c = y.total_cmp(x);
                if c != std::cmp::Ordering::Equal {
                    return c;
                }
            }
            for (x, y) in ka.iter().zip(kb.iter()) {
                let c = x.total_cmp(y);
                if c != std::cmp::Ordering::Equal {
                    return c;
                }
            }
            std::cmp::Ordering::Equal
        });
        let rows = rows
            .into_iter()
            .map(|(k, v)| {
                let mut row = Row::new();
                for ((_, name), val) in self.op.keys.iter().zip(k.into_iter()) {
                    row.insert(name.clone(), val);
                }
                for ((_, name), val) in self.op.aggs.iter().zip(v.into_iter()) {
                    row.insert(name.clone(), val);
                }
                row
            })
            .collect();
        Table { columns, rows }
    }
}

pub struct SortState {
    pub op: SortOp,
    rows: Vec<Record>,
    columns: Vec<String>,
}

impl SortState {
    pub fn new(op: SortOp) -> SortState {
        SortState { op, rows: Vec::new(), columns: Vec::new() }
    }
    pub fn reset(&mut self) {
        self.rows.clear();
        self.columns.clear();
    }
    pub fn process(&mut self, rec: &Record) {
        for k in rec.fields.keys() {
            if !self.columns.contains(k) {
                self.columns.push(k.clone());
            }
        }
        self.rows.push(rec.clone());
    }
    pub fn set_columns(&mut self, cols: &[String]) {
        self.columns = cols.to_vec();
    }
    pub fn emit(&self) -> Table {
        let mut rows = self.rows.clone();
        let op = &self.op;
        rows.sort_by(|a, b| {
            for e in &op.exprs {
                let va = e.eval(a).unwrap_or(Value::None);
                let vb = e.eval(b).unwrap_or(Value::None);
                let c = if op.desc { vb.total_cmp(&va) } else { va.total_cmp(&vb) };
                if c != std::cmp::Ordering::Equal {
                    return c;
                }
            }
            a.fields.cmp(&b.fields)
        });
        let mut columns = self.columns.clone();
        columns.sort();
        let rows = rows
            .into_iter()
            .map(|r| {
                let mut row = Row::new();
                for (k, v) in r.fields {
                    row.insert(k, v);
                }
                row
            })
            .collect();
        Table { columns, rows }
    }
}

pub enum Stage {
    Agg(MultiAggState),
    Sort(SortState),
    Inline(InlineState),
}

impl Stage {
    pub fn from_operator(op: Operator) -> Stage {
        match op {
            Operator::Agg(a) => Stage::Agg(MultiAggState::new(a)),
            Operator::Sort(s) => Stage::Sort(SortState::new(s)),
            Operator::Inline(i) => Stage::Inline(InlineState::new(i)),
        }
    }
}

/// Apply a chain of stages (after the first aggregate) to an input table.
pub fn run_stages(stages: &mut [Stage], mut table: Table) -> Table {
    for stage in stages.iter_mut() {
        match stage {
            Stage::Agg(a) => {
                a.reset();
                for row in &table.rows {
                    a.process(&Table::row_to_record(row));
                }
                table = a.emit();
            }
            Stage::Sort(s) => {
                s.reset();
                s.set_columns(&table.columns);
                for row in &table.rows {
                    s.process(&Table::row_to_record(row));
                }
                let mut t = s.emit();
                // keep the incoming column order first, then any new columns
                let mut cols = table.columns.clone();
                for c in &t.columns {
                    if !cols.contains(c) {
                        cols.push(c.clone());
                    }
                }
                t.columns = cols;
                table = t;
            }
            Stage::Inline(inl) => {
                inl.reset();
                let mut out_rows: Vec<Row> = Vec::new();
                for row in &table.rows {
                    if !inl.accepting() {
                        break;
                    }
                    if let Some(r) = inl.process(Table::row_to_record(row)) {
                        out_rows.push(r.fields.into_iter().collect());
                    }
                }
                for r in inl.finish() {
                    out_rows.push(r.fields.into_iter().collect());
                }
                let mut cols: Vec<String> = Vec::new();
                for c in &table.columns {
                    if out_rows.iter().any(|r| r.contains_key(c)) {
                        cols.push(c.clone());
                    }
                }
                for r in &out_rows {
                    let mut keys: Vec<&String> = r.keys().collect();
                    keys.sort();
                    for k in keys {
                        if !cols.contains(k) {
                            cols.push(k.clone());
                        }
                    }
                }
                table = Table { columns: cols, rows: out_rows };
            }
        }
    }
    table
}
EOF
