//! Diagnostic rendering in the style of annotate-snippets.

#[derive(Clone, Debug)]
pub struct Diag {
    pub title: String,
    pub span: (usize, usize),
    pub label: Option<String>,
    pub marker: char,
    pub footers: Vec<String>,
}

impl Diag {
    pub fn new(title: &str, span: (usize, usize)) -> Diag {
        Diag { title: title.to_string(), span, label: None, marker: '^', footers: Vec::new() }
    }
    pub fn label(mut self, l: &str) -> Diag {
        self.label = Some(l.to_string());
        self
    }
    pub fn marker(mut self, m: char) -> Diag {
        self.marker = m;
        self
    }
    pub fn help(mut self, h: &str) -> Diag {
        self.footers.push(h.to_string());
        self
    }

    pub fn render(&self, src: &str, kind: &str) -> String {
        let mut out = String::new();
        out.push_str(&format!("{}: {}\n", kind, self.title));
        // find the line containing the span start
        let (start, end) = self.span;
        let start = start.min(src.len());
        let end = end.min(src.len()).max(start);
        let line_start = src[..start].rfind('\n').map(|p| p + 1).unwrap_or(0);
        let line_end = src[line_start..].find('\n').map(|p| p + line_start).unwrap_or(src.len());
        let line_no = src[..line_start].matches('\n').count() + 1;
        let line = &src[line_start..line_end];
        let gutter = line_no.to_string().len();
        let pad = " ".repeat(gutter);
        out.push_str(&format!("{} |\n", pad));
        out.push_str(&format!("{} | {}\n", line_no, line));
        let col_start = src[line_start..start].chars().count();
        let span_len = src[start..end.max(start)].chars().count();
        let mut underline = format!("{} | {}", pad, " ".repeat(col_start));
        underline.push_str(&self.marker.to_string().repeat(span_len));
        if let Some(l) = &self.label {
            if span_len > 0 {
                underline.push(' ');
            }
            underline.push_str(l);
        }
        out.push_str(&underline);
        out.push('\n');
        out.push_str(&format!("{} |\n", pad));
        for f in &self.footers {
            out.push_str(&format!("{} = help: {}\n", pad, f));
        }
        out
    }
}
EOF
