{"command":"cd /workspace && cat > src/parser.rs <<'EOF'
//! Query parser. Hand-rolled recursive descent that replicates the observable
//! behaviour (including error messages) of the original tool.

use crate::diag::Diag;
use crate::expr::{BinOp, Expr, PathElem};
use crate::filter::Filter;
use crate::ops::{AggFunc, FieldMode, InlineOp, MultiAgg, Operator, SortOp};
use crate::value::Value;
use chrono::TimeDelta;
use regex::Regex;
use std::cell::RefCell;
use std::collections::HashMap;

pub struct Aliases {
    pub map: HashMap<String, Vec<Operator>>,
}

pub struct Query {
    pub filter: Filter,
    pub operators: Vec<Operator>,
}

/// Semantic (post-parse) errors
#[derive(Debug)]
pub enum SemanticError {
    Plain(String),
    WithDiag(Diag, String),
}

pub const KNOWN_OPERATORS: &[&str] = &[
    "json", "logfmt", "parse", "where", "limit", "fields", "split", "total", "timeslice", "sort", "count", "sum",
    "min", "max", "avg", "average", "count_distinct",
];
const INLINE_KEYWORDS: &[&str] =
    &["json", "logfmt", "parse", "where", "limit", "fields", "split", "total", "timeslice", "sort"];
const AGG_KEYWORDS: &[&str] = &["count", "sum", "min", "max", "avg", "average", "count_distinct"];

pub struct Parser<'a> {
    src: &'a str,
    pub errors: RefCell<Vec<Diag>>,
    aliases: Option<&'a Aliases>,
    /// semantic errors discovered during parsing (reported after parsing if no parse errors)
    pub semantic: RefCell<Vec<SemanticError>>,
    in_alias: bool,
}

type PResult<'a, T> = Option<(&'a str, T)>;

fn is_ident_start(c: char) -> bool {
    c.is_ascii_alphabetic() || c == '_'
}
fn is_ident_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

pub fn ws0(i: &str) -> &str {
    i.trim_start_matches(|c: char| c.is_whitespace())
}
pub fn ws1(i: &str) -> Option<&str> {
    let r = ws0(i);
    if r.len() == i.len() {
        None
    } else {
        Some(r)
    }
}
fn tag<'a>(i: &'a str, t: &str) -> Option<&'a str> {
    i.strip_prefix(t)
}
fn take_till_seg(i: &str) -> &str {
    let n = i.find(|c| c == '|' || c == ')').unwrap_or(i.len());
    &i[..n]
}
fn take_word(i: &str) -> &str {
    let n = i.find(|c: char| c.is_whitespace()).unwrap_or(i.len());
    &i[..n]
}
fn skip_to_pipe(i: &str) -> &str {
    match i.find('|') {
        Some(n) => &i[n..],
        None => &i[i.len()..],
    }
}

/// Parse a quoted string literal (single or double quotes) with escapes.
/// Returns (rest, content, terminated)
pub fn parse_string_lit(i: &str) -> Option<(&str, String, bool)> {
    let mut chars = i.char_indices();
    let (_, q) = chars.next()?;
    if q != '"' && q != '\'' {
        return None;
    }
    let mut out = String::new();
    let mut escaped = false;
    for (idx, c) in chars {
        if escaped {
            match c {
                'n' => out.push('\n'),
                'r' => out.push('\r'),
                't' => out.push('\t'),
                '0' => out.push('\0'),
                '\\' => out.push('\\'),
                '"' => out.push('"'),
                '\'' => out.push('\''),
                other => {
                    out.push('\\');
                    out.push(other);
                }
            }
            escaped = false;
        } else if c == '\\' {
            escaped = true;
        } else if c == q {
            return Some((&i[idx + 1..], out, true));
        } else {
            out.push(c);
        }
    }
    Some((&i[i.len()..], out, false))
}

impl<'a> Parser<'a> {
    pub fn new(src: &'a str, aliases: Option<&'a Aliases>) -> Parser<'a> {
        Parser { src, errors: RefCell::new(Vec::new()), aliases, semantic: RefCell::new(Vec::new()), in_alias: false }
    }

    pub fn for_alias(src: &'a str) -> Parser<'a> {
        let mut p = Parser::new(src, None);
        p.in_alias = true;
        p
    }

    fn pos(&self, i: &str) -> usize {
        self.src.len() - i.len()
    }

    fn record(&self, d: Diag) {
        self.errors.borrow_mut().push(d);
    }

    fn has_errors(&self) -> bool {
        !self.errors.borrow().is_empty()
    }

    fn span_of(&self, i: &str, text: &str) -> (usize, usize) {
        let s = self.pos(i);
        (s, s + text.len())
    }

    /// Span used by the "expecting an expression" diagnostics.
    fn missing_expr_span(&self, i: &'a str) -> (usize, usize) {
        let after_ws = ws0(i);
        let p = self.pos(after_ws);
        let s = take_till_seg(after_ws);
        if s.is_empty() {
            if p > 0 {
                (p - 1, p)
            } else {
                (p, p + 1)
            }
        } else {
            (p, p + s.len())
        }
    }

    fn expecting_expression(&self, i: &'a str) {
        self.record(Diag::new("expecting an expression", self.missing_expr_span(i)));
    }

    // -----------------------------------------------------------------------
    // Top level

    pub fn parse_query(&self) -> Result<Query, ()> {
        let i = ws0(self.src);
        let (i, filter) = match self.parse_filter(i) {
            Some(x) => x,
            None => return Err(()),
        };
        let i = ws0(i);
        if !i.is_empty() && !i.starts_with('|') {
            return Err(());
        }
        let operators = self.parse_pipeline(i);
        Ok(Query { filter, operators })
    }

    /// Parse `(| operator)*`
    fn parse_pipeline(&self, mut i: &'a str) -> Vec<Operator> {
        let mut ops = Vec::new();
        loop {
            i = ws0(i);
            if !i.starts_with('|') {
                break;
            }
            i = &i[1..];
            let (rest, mut parsed) = self.parse_operator(i);
            ops.append(&mut parsed);
            i = rest;
        }
        ops
    }

    /// Parse an alias template: operator (| operator)*
    pub fn parse_template(&self) -> Vec<Operator> {
        let i = ws0(self.src);
        let (rest, mut ops) = self.parse_operator(i);
        let mut more = self.parse_pipeline(rest);
        ops.append(&mut more);
        ops
    }

    // -----------------------------------------------------------------------
    // Filters

    fn parse_filter(&self, i: &'a str) -> PResult<'a, Filter> {
        // sequence of terms joined by implicit AND
        let (mut i, first) = self.parse_filter_term(i, true, 4)?;
        let mut terms = vec![first];
        loop {
            let after_ws = ws0(i);
            if after_ws.is_empty() || after_ws.starts_with('|') || after_ws.starts_with(')') {
                break;
            }
            let adjacent = after_ws.len() == i.len();
            match self.parse_filter_term(after_ws, false, if adjacent { 1 } else { 4 }) {
                Some((rest, t)) => {
                    terms.push(t);
                    i = rest;
                }
                None => break,
            }
        }
        let f = if terms.len() == 1 { terms.pop().unwrap() } else { Filter::And(terms) };
        Some((i, f))
    }

    /// term := and_expr (ws OR ws and_expr)?
    fn parse_filter_term(&self, i: &'a str, _first: bool, mult: usize) -> PResult<'a, Filter> {
        let (i, left) = self.parse_filter_and(i, mult)?;
        if let Some(r) = ws1(i) {
            if let Some(r) = tag(r, "OR") {
                if let Some(r) = ws1(r) {
                    if let Some((rest, right)) = self.parse_filter_and(r, 2) {
                        return Some((rest, Filter::Or(Box::new(left), Box::new(right))));
                    }
                }
            }
        }
        Some((i, left))
    }

    fn parse_filter_and(&self, i: &'a str, mult: usize) -> PResult<'a, Filter> {
        let (i, left) = self.parse_filter_atom(i, mult)?;
        if let Some(r) = ws1(i) {
            if let Some(r) = tag(r, "AND") {
                if let Some(r) = ws1(r) {
                    if let Some((rest, right)) = self.parse_filter_atom(r, 2) {
                        return Some((rest, Filter::And(vec![left, right])));
                    }
                }
            }
        }
        Some((i, left))
    }

    fn parse_filter_atom(&self, i: &'a str, mult: usize) -> PResult<'a, Filter> {
        if let Some(r) = tag(i, "NOT") {
            if let Some(r) = ws1(r) {
                if let Some((rest, inner)) = self.parse_filter_atom(r, mult) {
                    return Some((rest, Filter::Not(Box::new(inner))));
                }
            }
        }
        if let Some(r) = tag(i, "(") {
            let (r2, inner) = self.parse_filter(r)?;
            if let Some(rest) = tag(r2, ")") {
                return Some((rest, inner));
            }
            if r2.is_empty() {
                for _ in 0..mult {
                    self.record(
                        Diag::new("unterminated parenthesized filter", self.span_of(i, &i[..i.len() - r2.len()]))
                            .label("unterminated parenthesized filter")
                            .help("Insert a right parenthesis to terminate this filter"),
                    );
                }
            } else {
                let s = take_till_seg(r2);
                for _ in 0..mult {
                    self.record(Diag::new("unhandled input", self.span_of(r2, s)));
                }
            }
            return None;
        }
        if i.starts_with('"') || i.starts_with('\'') {
            let (rest, content, terminated) = parse_string_lit(i)?;
            if !terminated {
                let which = if i.starts_with('"') { "double" } else { "single" };
                let q = if i.starts_with('"') { "\"" } else { "'" };
                for _ in 0..mult {
                    self.record(
                        Diag::new(&format!("unterminated {} quoted string", which), self.span_of(i, i)).help(
                            &format!("Insert a {} quote ({}) to terminate this string", which, q),
                        ),
                    );
                }
                return None;
            }
            return Some((rest, Filter::Exact(content)));
        }
        // keyword
        let n = i
            .find(|c: char| !(c.is_ascii_alphanumeric() || "*_-./:@#$%^+".contains(c)))
            .unwrap_or(i.len());
        if n == 0 {
            return None;
        }
        let kw = &i[..n];
        if kw == "*" {
            return Some((&i[n..], Filter::All));
        }
        Some((&i[n..], Filter::Keyword(kw.to_string())))
    }

    // -----------------------------------------------------------------------
    // Operators

    fn end_of_segment(&self, i: &'a str) -> bool {
        let r = ws0(i);
        r.is_empty() || r.starts_with('|')
    }

    /// After a keyword operator: check for trailing garbage; record `msg` and skip to the pipe.
    fn finish_keyword_op(&self, i: &'a str, msg: &str) -> &'a str {
        let r = ws0(i);
        if r.is_empty() || r.starts_with('|') {
            return r;
        }
        let s = take_till_seg(r);
        self.record(Diag::new(msg, self.span_of(r, s)));
        skip_to_pipe(r)
    }

    fn parse_operator(&self, i: &'a str) -> (&'a str, Vec<Operator>) {
        let start = ws0(i);
        // keyword inline operators
        if let Some((rest, op)) = self.parse_keyword_op(start) {
            return (rest, vec![op]);
        }
        // strict aggregate
        if let Some((rest, op)) = self.parse_multi_agg(start) {
            return (rest, vec![op]);
        }
        // field expression
        if let Some((rest, op)) = self.parse_field_expr(start) {
            return (rest, vec![op]);
        }
        // validation of aggregate list (reports "Not an aggregate operator")
        if let Some(rest) = self.parse_agg_validation(start) {
            return (rest, vec![]);
        }
        // fallback
        if let Some((rest, name)) = self.parse_var_name(start) {
            if KNOWN_OPERATORS.contains(&name.as_str()) || name.starts_with('p') && name[1..].chars().all(|c| c.is_ascii_digit()) && name.len() > 1 && false {
                return (skip_to_pipe(rest), vec![]);
            }
            if let Some(al) = self.aliases {
                if let Some(ops) = al.map.get(&name) {
                    return (rest, ops.clone());
                }
            }
            if !self.has_errors() {
                let mut d = Diag::new("Expected an operator", self.span_of(start, &start[..start.len() - rest.len()]))
                    .help(&format!("{} is not a valid operator", name));
                if let Some(s) = suggest(&name) {
                    d = d.help(&format!("Did you mean \"{}\"?", s));
                }
                self.record(d);
            }
            return (skip_to_pipe(rest), vec![]);
        }
        if let Some((_rest, _e)) = self.parse_expr(start) {
            if !self.has_errors() {
                let s = take_till_seg(start);
                self.record(Diag::new("unrecognized syntax", self.span_of(start, s)));
            }
            return (skip_to_pipe(start), vec![]);
        }
        self.expecting_expression(i);
        (skip_to_pipe(start), vec![])
    }

    fn parse_keyword_op(&self, i: &'a str) -> PResult<'a, Operator> {
        if let Some(r) = tag(i, "json") {
            return self.parse_json_like(r, true);
        }
        if let Some(r) = tag(i, "logfmt") {
            return self.parse_json_like(r, false);
        }
        if let Some(r) = tag(i, "parse") {
            return self.parse_parse(r);
        }
        if let Some(r) = tag(i, "where") {
            return self.parse_where(r);
        }
        if let Some(r) = tag(i, "limit") {
            return self.parse_limit(r);
        }
        if let Some(r) = tag(i, "fields") {
            return self.parse_fields(r);
        }
        if let Some(r) = tag(i, "split") {
            return self.parse_split(r);
        }
        if let Some(r) = tag(i, "total") {
            return self.parse_total(r);
        }
        if let Some(r) = tag(i, "timeslice") {
            return self.parse_timeslice(r);
        }
        if let Some(r) = tag(i, "sort") {
            return self.parse_sort(r);
        }
        None
    }

    fn parse_json_like(&self, i: &'a str, is_json: bool) -> PResult<'a, Operator> {
        let mut from = None;
        let mut rest = i;
        if let Some(r) = ws1(i) {
            if let Some(r2) = tag(r, "from") {
                match ws1(r2).and_then(|r3| self.parse_expr(r3)) {
                    Some((r4, e)) => {
                        from = Some(e);
                        rest = r4;
                    }
                    None => {
                        let msg = if is_json {
                            "expecting an expression that supplies a JSON-encoded string"
                        } else {
                            "expecting an expression that supplies a logfmt-serialized string"
                        };
                        self.record(
                            Diag::new(msg, self.span_of(r, "from")).label("should be followed by an expression"),
                        );
                        return Some((skip_to_pipe(r2), Operator::Inline(InlineOp::NoOp)));
                    }
                }
            }
        }
        let rest = self.finish_keyword_op(rest, "unrecognized option, only the 'from' option is available");
        let op = if is_json { InlineOp::Json { from } } else { InlineOp::Logfmt { from } };
        Some((rest, Operator::Inline(op)))
    }

    fn expect_quoted(&self, i: &'a str) -> Option<(&'a str, String)> {
        if i.starts_with('"') || i.starts_with('\'') {
            let (rest, content, terminated) = parse_string_lit(i)?;
            if !terminated {
                let which = if i.starts_with('"') { "double" } else { "single" };
                let q = if i.starts_with('"') { "\"" } else { "'" };
                self.record(
                    Diag::new(&format!("unterminated {} quoted string", which), self.span_of(i, i))
                        .help(&format!("Insert a {} quote ({}) to terminate this string", which, q)),
                );
                return None;
            }
            Some((rest, content))
        } else {
            let w = take_word(i);
            self.record(
                Diag::new("expecting a quoted string", self.span_of(i, w))
                    .help("Enclose the text in a single or double-quoted string"),
            );
            None
        }
    }

    fn parse_parse(&self, i: &'a str) -> PResult<'a, Operator> {
        let r = ws1(i)?;
        let (r, is_regex) = match tag(r, "regex").and_then(ws1) {
            Some(r2) => (r2, true),
            None => (r, false),
        };
        let pat_start = r;
        let (mut r, pattern) = match self.expect_quoted(r) {
            Some(x) => x,
            None => return Some((skip_to_pipe(r), Operator::Inline(InlineOp::NoOp))),
        };
        let pat_text = &pat_start[..pat_start.len() - r.len()];
        let mut from = None;
        let mut fields: Vec<String> = Vec::new();
        let mut nodrop = false;
        let mut noconvert = false;
        // from
        if let Some(r2) = ws1(r).and_then(|x| tag(x, "from")).and_then(ws1) {
            if let Some((r3, e)) = self.parse_expr(r2) {
                from = Some(e);
                r = r3;
            }
        }
        // as
        if let Some(r2) = ws1(r).and_then(|x| tag(x, "as")) {
            if is_regex {
                let as_text = take_till_seg(r2);
                let full = &r2[..as_text.len()];
                let span_start = self.pos(r2) - 2;
                let span_end = span_start + 2 + full.trim_end().len();
                self.record(
                    Diag::new("the parse regex operator does not support an 'as' clause", (span_start, span_end))
                        .label("remove this")
                        .help("remove the 'as' clause, the named capture groups in the regular expression determine the output column"),
                );
                return Some((skip_to_pipe(r2), Operator::Inline(InlineOp::NoOp)));
            }
            if let Some(r3) = ws1(r2) {
                if let Some((r4, names)) = self.parse_var_list(r3) {
                    if !names.is_empty() {
                        fields = names;
                        r = r4;
                    }
                }
            }
        }
        // nodrop / noconvert in any order
        loop {
            if let Some(r2) = ws1(r).and_then(|x| tag(x, "nodrop")) {
                nodrop = true;
                r = r2;
                continue;
            }
            if let Some(r2) = ws1(r).and_then(|x| tag(x, "noconvert")) {
                noconvert = true;
                r = r2;
                continue;
            }
            break;
        }
        let rest = self.finish_keyword_op(r, "unrecognized option, only the 'from' and 'nodrop' options are available");
        if is_regex {
            match Regex::new(&pattern) {
                Ok(re) => {
                    let unnamed = re.captures_len() - 1 - re.capture_names().flatten().count();
                    if unnamed > 0 {
                        self.record(
                            Diag::new(
                                "regular expression for the parse operator cannot have unnamed captures",
                                self.span_of(pat_start, pat_text),
                            )
                            .label(&format!("contains {} unnamed capture(s)", unnamed))
                            .help("name the capture groups by adding -- ?P<capname> -- right after the left parenthesis"),
                        );
                        return Some((rest, Operator::Inline(InlineOp::NoOp)));
                    }
                    Some((rest, Operator::Inline(InlineOp::ParseRegex { regex: re, from, nodrop, noconvert })))
                }
                Err(e) => {
                    self.record(
                        Diag::new("invalid regular expression", self.span_of(pat_start, pat_text))
                            .label(&format!("{}", e)),
                    );
                    Some((rest, Operator::Inline(InlineOp::NoOp)))
                }
            }
        } else {
            let (re, nstars) = pattern_to_regex(&pattern);
            if nstars != fields.len() {
                self.semantic.borrow_mut().push(SemanticError::Plain(format!(
                    "Wrong number of patterns for parse. Pattern has {} but {} were extracted",
                    nstars,
                    fields.len()
                )));
            }
            let regex = Regex::new(&re).unwrap_or_else(|_| Regex::new("$^").unwrap());
            Some((rest, Operator::Inline(InlineOp::Parse { regex, fields, from, nodrop, noconvert })))
        }
    }

    fn parse_where(&self, i: &'a str) -> PResult<'a, Operator> {
        let kw_span = (self.pos(i) - 5, self.pos(i));
        if i.is_empty() {
            self.semantic.borrow_mut().push(SemanticError::WithDiag(
                Diag::new("Expected an expression", kw_span)
                    .label("No condition provided for this 'where'")
                    .help("Insert an expression whose result determines whether a record should be passed downstream")
                    .help("example: where duration > 100"),
                "Expected an expression".to_string(),
            ));
            return Some((i, Operator::Inline(InlineOp::Where(None))));
        }
        let r = ws1(i)?;
        match self.parse_expr(r) {
            Some((r2, e)) => {
                let rest = self.finish_keyword_op(r2, "unrecognized option, only the condition can be specified");
                Some((rest, Operator::Inline(InlineOp::Where(Some(e)))))
            }
            None => {
                self.expecting_expression(i);
                Some((skip_to_pipe(r), Operator::Inline(InlineOp::NoOp)))
            }
        }
    }

    fn parse_limit(&self, i: &'a str) -> PResult<'a, Operator> {
        let mut limit: Option<i64> = None;
        let mut rest = i;
        if let Some(r) = ws1(i) {
            // number: [+-]?digits(.digits)?
            let mut n = 0;
            let b = r.as_bytes();
            if n < b.len() && (b[n] == b'+' || b[n] == b'-') {
                n += 1;
            }
            let ds = n;
            while n < b.len() && b[n].is_ascii_digit() {
                n += 1;
            }
            if n > ds {
                if n < b.len() && b[n] == b'.' {
                    let mut m = n + 1;
                    while m < b.len() && b[m].is_ascii_digit() {
                        m += 1;
                    }
                    if m > n + 1 {
                        n = m;
                    }
                }
                let text = &r[..n];
                if let Ok(f) = text.parse::<f64>() {
                    rest = &r[n..];
                    let span = self.span_of(r, text);
                    if f == 0.0 {
                        let msg = format!("Limit must be a non-zero integer, found {}", f);
                        self.semantic.borrow_mut().push(SemanticError::WithDiag(
                            Diag::new(&msg, span)
                                .label("Zero is not allowed")
                                .help("Use a positive integer to select the first N rows")
                                .help("Use a negative integer to select the last N rows"),
                            msg.clone(),
                        ));
                    } else if f.fract() != 0.0 {
                        let msg = format!("Limit must be a non-zero integer, found {}", f);
                        self.semantic.borrow_mut().push(SemanticError::WithDiag(
                            Diag::new(&msg, span)
                                .label("Fractional limits are not allowed")
                                .help("Use a positive integer to select the first N rows")
                                .help("Use a negative integer to select the last N rows"),
                            msg.clone(),
                        ));
                    } else {
                        limit = Some(f as i64);
                    }
                }
            }
        }
        let rest = self.finish_keyword_op(rest, "unrecognized option, only the numeric limit can be specified");
        Some((rest, Operator::Inline(InlineOp::Limit(limit))))
    }

    fn parse_fields(&self, i: &'a str) -> PResult<'a, Operator> {
        let r = ws1(i)?;
        let (r, mode) = if let Some(r2) = tag(r, "only").and_then(ws1) {
            (r2, FieldMode::Only)
        } else if let Some(r2) = tag(r, "except").and_then(ws1) {
            (r2, FieldMode::Except)
        } else if let Some(r2) = tag(r, "+") {
            (ws0(r2), FieldMode::Only)
        } else if let Some(r2) = tag(r, "-") {
            (ws0(r2), FieldMode::Except)
        } else {
            (r, FieldMode::Only)
        };
        let (rest, names) = self.parse_var_list(r)?;
        if names.is_empty() {
            return None;
        }
        Some((rest, Operator::Inline(InlineOp::Fields { mode, names })))
    }

    fn parse_split(&self, i: &'a str) -> PResult<'a, Operator> {
        let mut r = i;
        let mut input = None;
        if let Some(r2) = tag(i, "(") {
            let r3 = ws0(r2);
            let (r4, e) = self.parse_expr(r3)?;
            let r5 = ws0(r4);
            let r6 = tag(r5, ")")?;
            input = Some(e);
            r = r6;
        }
        let mut sep = ",".to_string();
        let mut output = None;
        if let Some(r2) = ws1(r).and_then(|x| tag(x, "on")).and_then(ws1) {
            match self.expect_quoted(r2) {
                Some((r3, s)) => {
                    sep = s;
                    r = r3;
                }
                None => return Some((skip_to_pipe(r2), Operator::Inline(InlineOp::NoOp))),
            }
        }
        if let Some(r2) = ws1(r).and_then(|x| tag(x, "as")).and_then(ws1) {
            if let Some((r3, e)) = self.parse_expr(r2) {
                output = Some(e);
                r = r3;
            }
        }
        let rest = self.finish_keyword_op(r, "unrecognized option, only the 'on' and 'as' options are available");
        Some((rest, Operator::Inline(InlineOp::Split { input, sep, output })))
    }

    /// Parse `(expr)` for single-argument operators (total, timeslice, sum, ...).
    /// `desc` is the description used in error messages.
    /// Returns None (after recording) on hard failures where the segment should be skipped.
    fn parse_single_arg(&self, kw_end: &'a str, desc: &str) -> Result<(&'a str, Expr), &'a str> {
        let i = kw_end;
        let r = match tag(i, "(") {
            Some(r) => r,
            None => {
                let s = take_till_seg(i);
                self.record(Diag::new(
                    &format!("expecting a parenthesized argument that supplies {}", desc),
                    self.span_of(i, s),
                ));
                return Err(skip_to_pipe(i));
            }
        };
        let paren_pos = self.pos(i);
        let r2 = ws0(r);
        if r2.starts_with(')') || r2.is_empty() {
            // zero arguments
            let after = if r2.starts_with(')') { &r2[1..] } else { r2 };
            let p = self.pos(after) + if r2.starts_with(')') { 0 } else { 1 };
            self.record(
                Diag::new("this operator takes 1 argument, but 0 were supplied", (p, p + 1))
                    .label("supplied 0 arguments")
                    .marker('-')
                    .help(&format!("the argument should supply {}", desc)),
            );
            if r2.is_empty() {
                self.record(
                    Diag::new("unterminated function call", (paren_pos, self.src.len()))
                        .label("unterminated function call")
                        .help("Insert a right parenthesis to terminate this call"),
                );
            }
            return Err(skip_to_pipe(after));
        }
        match self.parse_expr(r2) {
            Some((r3, e)) => {
                if let Some(r4) = tag(r3, ")") {
                    Ok((r4, e))
                } else if r3.is_empty() {
                    self.record(
                        Diag::new("unterminated function call", (paren_pos, self.src.len()))
                            .label("unterminated function call")
                            .help("Insert a right parenthesis to terminate this call"),
                    );
                    Err(r3)
                } else {
                    let s = take_till_seg(r3);
                    self.record(Diag::new("unhandled input", self.span_of(r3, s)));
                    Err(skip_to_pipe(r3))
                }
            }
            None => {
                self.expecting_expression(r2);
                Err(skip_to_pipe(r2))
            }
        }
    }

    fn parse_as_name(&self, i: &'a str) -> Option<(&'a str, Option<String>)> {
        // optional ` as name`
        if let Some(r) = ws1(i).and_then(|x| tag(x, "as")) {
            match ws1(r) {
                Some(r2) => match self.parse_var_name(r2) {
                    Some((r3, n)) => return Some((r3, Some(n))),
                    None => {
                        let s = take_till_seg(r2);
                        let span = if s.is_empty() { (self.pos(r2), self.pos(r2)) } else { self.span_of(r2, take_word(r2)) };
                        self.record(Diag::new("expecting a name for the field", span).help("Give the value a name"));
                        return None;
                    }
                },
                None => {
                    // "as" at EOF / followed by nothing: leave for the end-check
                    return Some((i, None));
                }
            }
        }
        Some((i, None))
    }

    fn parse_total(&self, i: &'a str) -> PResult<'a, Operator> {
        let (r, e) = match self.parse_single_arg(i, "the value to sum") {
            Ok(x) => x,
            Err(rest) => return Some((rest, Operator::Inline(InlineOp::NoOp))),
        };
        let (r, name) = match self.parse_as_name(r) {
            Some(x) => x,
            None => return Some((skip_to_pipe(r), Operator::Inline(InlineOp::NoOp))),
        };
        let rest = self.finish_keyword_op(r, "unrecognized option, only the 'as' option is available");
        Some((rest, Operator::Inline(InlineOp::Total { expr: e, name: name.unwrap_or_else(|| "_total".to_string()) })))
    }

    fn parse_timeslice(&self, i: &'a str) -> PResult<'a, Operator> {
        let (r, e) = match self.parse_single_arg(i, "the date-time value for the log message") {
            Ok(x) => x,
            Err(rest) => return Some((rest, Operator::Inline(InlineOp::NoOp))),
        };
        let mut duration = None;
        let mut r = r;
        if let Some(r2) = ws1(r) {
            if let Some((r3, d)) = parse_duration(r2) {
                duration = Some(d);
                r = r3;
            }
        }
        if duration.is_none() && !self.in_alias {
            self.semantic
                .borrow_mut()
                .push(SemanticError::Plain("Expected a duration for the timeslice (e.g. 1h)".to_string()));
        }
        let (r, name) = match self.parse_as_name(r) {
            Some(x) => x,
            None => return Some((skip_to_pipe(r), Operator::Inline(InlineOp::NoOp))),
        };
        let rest = self.finish_keyword_op(r, "unrecognized option, only the 'as' option is available");
        Some((
            rest,
            Operator::Inline(InlineOp::Timeslice {
                expr: e,
                duration,
                name: name.unwrap_or_else(|| "_timeslice".to_string()),
            }),
        ))
    }

    fn parse_sort(&self, i: &'a str) -> PResult<'a, Operator> {
        let mut exprs = Vec::new();
        let mut desc = false;
        let mut rest = i;
        if let Some(r) = ws1(i).and_then(|x| tag(x, "by")) {
            if let Some(r2) = ws1(r) {
                match self.parse_expr_list(r2, true) {
                    Some((r3, list)) => {
                        exprs = list.into_iter().map(|(e, _)| e).collect();
                        rest = r3;
                        if let Some(r4) = ws1(rest) {
                            if let Some(r5) = tag(r4, "asc") {
                                rest = r5;
                            } else if let Some(r5) = tag(r4, "desc") {
                                desc = true;
                                rest = r5;
                            } else if let Some(r5) = tag(r4, "dsc") {
                                desc = true;
                                rest = r5;
                            }
                        }
                    }
                    None => {
                        return Some((skip_to_pipe(r2), Operator::Inline(InlineOp::NoOp)));
                    }
                }
            }
        }
        Some((rest, Operator::Sort(SortOp { exprs, desc })))
    }

    // -----------------------------------------------------------------------
    // Aggregates

    fn agg_desc(name: &str) -> &'static str {
        match name {
            "sum" => "the numeric value to find the sum of",
            "min" => "the numeric value to find the minimum of",
            "max" => "the numeric value to find the maximum of",
            "avg" | "average" => "the numeric value to find the average of",
            "count" => "the value to count",
            "count_distinct" => "the value to count distinct values of",
            _ => "the value to compute the percentile of",
        }
    }

    /// Parse a single aggregate function with optional alias. Returns Err(rest) if a hard error was recorded.
    fn parse_agg_func(&self, i: &'a str) -> Result<PResult<'a, (AggFunc, String)>, &'a str> {
        let (r, name) = match self.parse_ident(i) {
            Some(x) => x,
            None => return Ok(None),
        };
        let name_span = self.span_of(i, &i[..i.len() - r.len()]);
        let (func, default_name, r) = match name.as_str() {
            "count" => {
                if r.starts_with('(') {
                    match self.parse_single_arg(r, "the value to count") {
                        Ok((r2, e)) => (AggFunc::Count(Some(e)), "_count".to_string(), r2),
                        Err(rest) => return Err(rest),
                    }
                } else {
                    (AggFunc::Count(None), "_count".to_string(), r)
                }
            }
            "sum" | "min" | "max" | "avg" | "average" => {
                match self.parse_single_arg(r, Self::agg_desc(&name)) {
                    Ok((r2, e)) => {
                        let (f, n) = match name.as_str() {
                            "sum" => (AggFunc::Sum(e), "_sum"),
                            "min" => (AggFunc::Min(e), "_min"),
                            "max" => (AggFunc::Max(e), "_max"),
                            _ => (AggFunc::Avg(e), "_average"),
                        };
                        (f, n.to_string(), r2)
                    }
                    Err(rest) => return Err(rest),
                }
            }
            "count_distinct" => {
                // special arity error
                if let Some(r2) = tag(r, "(") {
                    let r3 = ws0(r2);
                    if let Some((r4, list)) = self.parse_expr_list(r3, false) {
                        let r5 = ws0(r4);
                        if let Some(r6) = tag(r5, ")") {
                            if list.len() != 1 {
                                let paren_text = &r[..r.len() - r6.len()];
                                self.record(
                                    Diag::new("Expecting a single expression to count", self.span_of(r, paren_text))
                                        .label("Only a single expression can be given")
                                        .help("example: count_distinct(field_to_count)"),
                                );
                                return Err(skip_to_pipe(r6));
                            }
                            let e = list.into_iter().next().unwrap().0;
                            (AggFunc::CountDistinct(e), "_countDistinct".to_string(), r6)
                        } else {
                            return Ok(None);
                        }
                    } else {
                        return Ok(None);
                    }
                } else {
                    return Ok(None);
                }
            }
            _ => {
                // percentile: p<digits> or pct<digits>
                let digits = if let Some(d) = name.strip_prefix("pct") {
                    d
                } else if let Some(d) = name.strip_prefix('p') {
                    d
                } else {
                    return Ok(None);
                };
                if digits.is_empty() || !digits.chars().all(|c| c.is_ascii_digit()) {
                    return Ok(None);
                }
                let n: f64 = digits.parse().unwrap_or(0.0);
                if n <= 0.0 || n >= 100.0 {
                    let dstart = name_span.1 - digits.len();
                    self.record(
                        Diag::new(&format!("invalid percentile number: {}", digits), (dstart, name_span.1))
                            .label("expecting a number between (0, 100)"),
                    );
                    return Err(skip_to_pipe(r));
                }
                match self.parse_single_arg(r, "the value to compute the percentile of") {
                    Ok((r2, e)) => (AggFunc::Percentile(e, n), format!("p{}", digits), r2),
                    Err(rest) => return Err(rest),
                }
            }
        };
        match self.parse_as_name(r) {
            Some((r2, Some(n))) => Ok(Some((r2, (func, n)))),
            Some((r2, None)) => Ok(Some((r2, (func, default_name)))),
            None => Err(skip_to_pipe(r)),
        }
    }

    fn parse_multi_agg(&self, i: &'a str) -> PResult<'a, Operator> {
        let mut aggs = Vec::new();
        let mut r = i;
        loop {
            match self.parse_agg_func(r) {
                Ok(Some((r2, a))) => {
                    aggs.push(a);
                    r = r2;
                }
                Ok(None) => {
                    if aggs.is_empty() {
                        return None;
                    }
                    return None;
                }
                Err(rest) => return Some((rest, Operator::Inline(InlineOp::NoOp))),
            }
            let r2 = ws0(r);
            if let Some(r3) = tag(r2, ",") {
                r = ws0(r3);
                continue;
            }
            break;
        }
        // by clause
        let mut keys = Vec::new();
        if let Some(r2) = ws1(r).and_then(|x| tag(x, "by")) {
            if let Some(r3) = ws1(r2) {
                match self.parse_expr_list(r3, true) {
                    Some((r4, list)) => {
                        keys = list;
                        r = r4;
                    }
                    None => return Some((skip_to_pipe(r3), Operator::Inline(InlineOp::NoOp))),
                }
            }
        }
        if !self.end_of_segment(r) {
            return None;
        }
        Some((ws0(r), Operator::Agg(MultiAgg { aggs, keys })))
    }

    /// The lenient aggregate list parser used for "Not an aggregate operator" diagnostics.
    fn parse_agg_validation(&self, i: &'a str) -> Option<&'a str> {
        let mut r = i;
        let mut idents: Vec<(String, (usize, usize))> = Vec::new();
        loop {
            let (r2, name) = self.parse_ident(r)?;
            let span = self.span_of(r, &r[..r.len() - r2.len()]);
            let mut r3 = r2;
            if let Some(r4) = tag(r2, "(") {
                let r5 = ws0(r4);
                let (r6, _) = self.parse_expr_list(r5, false)?;
                let r7 = ws0(r6);
                r3 = tag(r7, ")")?;
            }
            idents.push((name, span));
            let r4 = ws0(r3);
            if let Some(r5) = tag(r4, ",") {
                r = ws0(r5);
                continue;
            }
            r = r3;
            break;
        }
        if let Some(r2) = ws1(r).and_then(|x| tag(x, "by")) {
            if let Some(r3) = ws1(r2) {
                match self.parse_expr_list(r3, true) {
                    Some((r4, _)) => r = r4,
                    None => return Some(skip_to_pipe(r3)),
                }
            }
        }
        if !self.end_of_segment(r) {
            return None;
        }
        if idents.len() < 2 {
            return None;
        }
        for (name, span) in idents {
            if !AGG_KEYWORDS.contains(&name.as_str()) {
                let mut d = Diag::new("Not an aggregate operator", span)
                    .help(&format!("{} is not a valid aggregate operator", name));
                if INLINE_KEYWORDS.contains(&name.as_str()) {
                    d = d.help(&format!(
                        "{} is an inline operator, but only aggregate operators (count, average, etc.) are valid here",
                        name
                    ));
                }
                self.record(d);
            }
        }
        Some(ws0(r))
    }

    fn parse_field_expr(&self, i: &'a str) -> PResult<'a, Operator> {
        let (r, e) = self.parse_expr(i)?;
        let r2 = ws1(r)?;
        let r3 = tag(r2, "as")?;
        let r4 = ws1(r3)?;
        let (r5, name) = self.parse_var_name(r4)?;
        Some((r5, Operator::Inline(InlineOp::FieldExpr { expr: e, name })))
    }

    // -----------------------------------------------------------------------
    // Expressions

    pub fn parse_ident(&self, i: &'a str) -> PResult<'a, String> {
        let mut chars = i.char_indices();
        let (_, c) = chars.next()?;
        if !is_ident_start(c) {
            return None;
        }
        let mut end = c.len_utf8();
        for (idx, c) in chars {
            if is_ident_char(c) {
                end = idx + c.len_utf8();
            } else {
                break;
            }
        }
        Some((&i[end..], i[..end].to_string()))
    }

    /// identifier or ["quoted name"]
    pub fn parse_var_name(&self, i: &'a str) -> PResult<'a, String> {
        if let Some(r) = tag(i, "[") {
            let (r2, s, terminated) = parse_string_lit(r)?;
            if !terminated {
                return None;
            }
            let r3 = tag(r2, "]")?;
            return Some((r3, s));
        }
        self.parse_ident(i)
    }

    fn parse_var_list(&self, i: &'a str) -> PResult<'a, Vec<String>> {
        let mut names = Vec::new();
        let mut r = i;
        loop {
            match self.parse_var_name(r) {
                Some((r2, n)) => {
                    names.push(n);
                    r = r2;
                }
                None => break,
            }
            let r2 = ws0(r);
            if let Some(r3) = tag(r2, ",") {
                r = ws0(r3);
                continue;
            }
            break;
        }
        Some((r, names))
    }

    /// Parse a comma separated list of expressions (used for `by` clauses and function args).
    /// When `by_clause` is set, a missing expression records "expecting an expression" twice.
    fn parse_expr_list(&self, i: &'a str, by_clause: bool) -> PResult<'a, Vec<(Expr, String)>> {
        let mut list = Vec::new();
        let mut r = i;
        loop {
            match self.parse_expr(r) {
                Some((r2, e)) => {
                    let text = r[..r.len() - r2.len()].trim().to_string();
                    list.push((e, text));
                    r = r2;
                }
                None => {
                    if by_clause {
                        self.expecting_expression(r);
                        self.expecting_expression(r);
                        return None;
                    }
                    if list.is_empty() {
                        return Some((r, list));
                    }
                    return None;
                }
            }
            let r2 = ws0(r);
            if let Some(r3) = tag(r2, ",") {
                r = ws0(r3);
                continue;
            }
            break;
        }
        Some((r, list))
    }

    pub fn parse_expr(&self, i: &'a str) -> PResult<'a, Expr> {
        self.parse_or(i)
    }

    fn parse_or(&self, i: &'a str) -> PResult<'a, Expr> {
        let (mut r, mut left) = self.parse_and(i)?;
        loop {
            let (r2, kw) = if let Some(x) = ws1(r).and_then(|x| tag(x, "or")) {
                (x, true)
            } else if let Some(x) = tag(ws0(r), "||") {
                (x, false)
            } else {
                break;
            };
            let operand_start = if kw { ws1(r2) } else { Some(ws0(r2)) };
            match operand_start.and_then(|s| self.parse_and(s)) {
                Some((r3, right)) => {
                    left = Expr::Binary { op: BinOp::Or, l: Box::new(left), r: Box::new(right) };
                    r = r3;
                }
                None => {
                    let p = self.pos(r2);
                    self.record(
                        Diag::new("expecting an operand for 'or' operator", (p, p + 1))
                            .label("dangling binary operator")
                            .marker('-')
                            .help("Add the operand or delete the operator"),
                    );
                    return None;
                }
            }
        }
        Some((r, left))
    }

    fn parse_and(&self, i: &'a str) -> PResult<'a, Expr> {
        let (mut r, mut left) = self.parse_cmp(i)?;
        loop {
            let (r2, kw) = if let Some(x) = ws1(r).and_then(|x| tag(x, "and")) {
                (x, true)
            } else if let Some(x) = tag(ws0(r), "&&") {
                (x, false)
            } else {
                break;
            };
            let operand_start = if kw { ws1(r2) } else { Some(ws0(r2)) };
            match operand_start.and_then(|s| self.parse_cmp(s)) {
                Some((r3, right)) => {
                    left = Expr::Binary { op: BinOp::And, l: Box::new(left), r: Box::new(right) };
                    r = r3;
                }
                None => {
                    let p = self.pos(r2);
                    self.record(
                        Diag::new("expecting an operand for 'and' operator", (p, p + 1))
                            .label("dangling binary operator")
                            .marker('-')
                            .help("Add the operand or delete the operator"),
                    );
                    return None;
                }
            }
        }
        Some((r, left))
    }

    fn parse_cmp(&self, i: &'a str) -> PResult<'a, Expr> {
        let (r, left) = self.parse_add(i)?;
        let r2 = ws0(r);
        let ops: [(&str, BinOp); 7] = [
            ("==", BinOp::Eq),
            ("!=", BinOp::Ne),
            ("<>", BinOp::Ne),
            ("<=", BinOp::Le),
            (">=", BinOp::Ge),
            ("<", BinOp::Lt),
            (">", BinOp::Gt),
        ];
        for (sym, op) in ops.iter() {
            if let Some(r3) = tag(r2, sym) {
                let r4 = ws0(r3);
                match self.parse_add(r4) {
                    Some((r5, right)) => {
                        return Some((r5, Expr::Binary { op: op.clone(), l: Box::new(left), r: Box::new(right) }));
                    }
                    None => {
                        let p = self.pos(r4);
                        self.record(Diag::new("expecting the right-hand-side of the comparison", (p, p)));
                        return None;
                    }
                }
            }
        }
        Some((r, left))
    }

    fn parse_add(&self, i: &'a str) -> PResult<'a, Expr> {
        let (mut r, mut left) = self.parse_mul(i)?;
        loop {
            let r2 = ws0(r);
            let op = if r2.starts_with('+') {
                BinOp::Add
            } else if r2.starts_with('-') {
                BinOp::Sub
            } else {
                break;
            };
            let r3 = ws0(&r2[1..]);
            match self.parse_mul(r3) {
                Some((r4, right)) => {
                    left = Expr::Binary { op, l: Box::new(left), r: Box::new(right) };
                    r = r4;
                }
                None => {
                    let p = self.pos(r3);
                    self.record(
                        Diag::new("expecting an operand for binary operator", (p + 1, p + 2))
                            .label("dangling binary operator")
                            .marker('-')
                            .help("Add the operand or delete the operator"),
                    );
                    return None;
                }
            }
        }
        Some((r, left))
    }

    fn parse_mul(&self, i: &'a str) -> PResult<'a, Expr> {
        let (mut r, mut left) = self.parse_unary(i)?;
        loop {
            let r2 = ws0(r);
            let op = if r2.starts_with('*') {
                BinOp::Mul
            } else if r2.starts_with('/') {
                BinOp::Div
            } else {
                break;
            };
            let r3 = ws0(&r2[1..]);
            match self.parse_unary(r3) {
                Some((r4, right)) => {
                    left = Expr::Binary { op, l: Box::new(left), r: Box::new(right) };
                    r = r4;
                }
                None => {
                    let p = self.pos(r3);
                    self.record(
                        Diag::new("expecting an operand for binary operator", (p + 1, p + 2))
                            .label("dangling binary operator")
                            .marker('-')
                            .help("Add the operand or delete the operator"),
                    );
                    return None;
                }
            }
        }
        Some((r, left))
    }

    fn parse_unary(&self, i: &'a str) -> PResult<'a, Expr> {
        if let Some(r) = tag(i, "!") {
            if r.starts_with('=') {
                return None;
            }
            return match self.parse_unary(r) {
                Some((r2, e)) => Some((r2, Expr::Not(Box::new(e)))),
                None => {
                    let p = self.pos(r);
                    self.record(
                        Diag::new("expecting expression for unary operator", (p, p + 1))
                            .label("dangling unary operator")
                            .marker('-'),
                    );
                    None
                }
            };
        }
        self.parse_postfix(i)
    }

    fn parse_postfix(&self, i: &'a str) -> PResult<'a, Expr> {
        let (mut r, mut e) = self.parse_atom(i)?;
        loop {
            if let Some(r2) = tag(r, ".") {
                if let Some((r3, name)) = self.parse_var_name(r2) {
                    e = push_path(e, PathElem::Field(name))?;
                    r = r3;
                    continue;
                }
                break;
            }
            if let Some(r2) = tag(r, "[") {
                // integer index (optionally negative)
                let b = r2.as_bytes();
                let mut n = 0;
                if n < b.len() && b[n] == b'-' {
                    n += 1;
                }
                let ds = n;
                while n < b.len() && b[n].is_ascii_digit() {
                    n += 1;
                }
                if n > ds {
                    if let Some(r3) = tag(&r2[n..], "]") {
                        let idx: i64 = r2[..n].parse().unwrap_or(0);
                        e = push_path(e, PathElem::Index(idx))?;
                        r = r3;
                        continue;
                    }
                }
                break;
            }
            break;
        }
        Some((r, e))
    }

    fn parse_atom(&self, i: &'a str) -> PResult<'a, Expr> {
        let c = i.chars().next()?;
        if c.is_ascii_digit() {
            let n = i.find(|c: char| !c.is_ascii_digit()).unwrap_or(i.len());
            let v: i64 = i[..n].parse().unwrap_or(i64::MAX);
            return Some((&i[n..], Expr::Literal(Value::Int(v))));
        }
        if c == '"' || c == '\'' {
            let (rest, content, terminated) = parse_string_lit(i)?;
            if !terminated {
                let which = if c == '"' { "double" } else { "single" };
                let q = if c == '"' { "\"" } else { "'" };
                self.record(
                    Diag::new(&format!("unterminated {} quoted string", which), self.span_of(i, i))
                        .help(&format!("Insert a {} quote ({}) to terminate this string", which, q)),
                );
                return None;
            }
            return Some((rest, Expr::Literal(Value::Str(content))));
        }
        if c == '(' {
            let r = ws0(&i[1..]);
            let (r2, e) = self.parse_expr(r)?;
            if let Some(r3) = tag(r2, ")") {
                return Some((r3, e));
            }
            if r2.is_empty() {
                self.record(
                    Diag::new("unterminated parenthesized expression", (self.pos(i), self.src.len()))
                        .label("unterminated parenthesized expression")
                        .help("Insert a right parenthesis to terminate this expression"),
                );
            } else {
                let s = take_till_seg(r2);
                self.record(Diag::new("unhandled input", self.span_of(r2, s)));
            }
            return None;
        }
        if c == '[' {
            let (r, name) = self.parse_var_name(i)?;
            return Some((r, Expr::Column { name, path: vec![] }));
        }
        let (r, name) = self.parse_ident(i)?;
        match name.as_str() {
            "true" => return Some((r, Expr::Literal(Value::Bool(true)))),
            "false" => return Some((r, Expr::Literal(Value::Bool(false)))),
            "null" => return Some((r, Expr::Literal(Value::None))),
            _ => {}
        }
        if let Some(r2) = tag(r, "(") {
            // function call
            let paren_pos = self.pos(r);
            let r3 = ws0(r2);
            let (r4, args) = self.parse_expr_list(r3, false)?;
            let r5 = ws0(r4);
            match tag(r5, ")") {
                Some(r6) => {
                    if name == "if" {
                        if args.len() != 3 {
                            let paren_text = &r[..r.len() - r6.len()];
                            self.record(
                                Diag::new(
                                    "the 'if' operator expects exactly 3 arguments, the condition, value-if-true, and value-if-false",
                                    self.span_of(r, paren_text),
                                )
                                .label(&format!("supplied {} arguments", args.len())),
                            );
                            return None;
                        }
                        let mut it = args.into_iter().map(|(e, _)| e);
                        let cond = it.next().unwrap();
                        let then = it.next().unwrap();
                        let els = it.next().unwrap();
                        return Some((
                            r6,
                            Expr::If { cond: Box::new(cond), then: Box::new(then), els: Box::new(els) },
                        ));
                    }
                    let args = args.into_iter().map(|(e, _)| e).collect();
                    return Some((r6, Expr::Call { name, args }));
                }
                None => {
                    if r5.is_empty() {
                        self.record(
                            Diag::new("unterminated function call", (paren_pos, self.src.len()))
                                .label("unterminated function call")
                                .help("Insert a right parenthesis to terminate this call"),
                        );
                        return None;
                    }
                    return None;
                }
            }
        }
        Some((r, Expr::Column { name, path: vec![] }))
    }
}

fn push_path(e: Expr, p: PathElem) -> Option<Expr> {
    match e {
        Expr::Column { name, mut path } => {
            path.push(p);
            Some(Expr::Column { name, path })
        }
        _ => None,
    }
}

/// Convert a parse pattern ("* user=* took *") into a regex. Returns (regex, number of stars).
pub fn pattern_to_regex(p: &str) -> (String, usize) {
    let stars = p.matches('*').count();
    let mut out = String::from("(?i)");
    let mut seen = 0;
    for c in p.chars() {
        if c == '*' {
            seen += 1;
            if seen == stars && p.ends_with('*') {
                out.push_str("(.*)");
            } else {
                out.push_str("(.*?)");
            }
        } else if c.is_whitespace() {
            out.push_str("\\s");
        } else {
            out.push_str(&regex::escape(&c.to_string()));
        }
    }
    (out, stars)
}

pub fn parse_duration(i: &str) -> Option<(&str, TimeDelta)> {
    let n = i.find(|c: char| !c.is_ascii_digit()).unwrap_or(i.len());
    if n == 0 {
        return None;
    }
    let num: i64 = i[..n].parse().ok()?;
    let rest = &i[n..];
    let units: [(&str, fn(i64) -> TimeDelta); 8] = [
        ("ns", TimeDelta::nanoseconds),
        ("us", TimeDelta::microseconds),
        ("ms", TimeDelta::milliseconds),
        ("s", TimeDelta::seconds),
        ("m", TimeDelta::minutes),
        ("h", TimeDelta::hours),
        ("d", TimeDelta::days),
        ("w", TimeDelta::weeks),
    ];
    for (u, f) in units.iter() {
        if let Some(r) = rest.strip_prefix(u) {
            // the unit must not be followed by more letters
            if r.chars().next().map(|c| c.is_ascii_alphanumeric()).unwrap_or(false) {
                continue;
            }
            return Some((r, f(num)));
        }
    }
    None
}

pub fn suggest(name: &str) -> Option<&'static str> {
    for cand in KNOWN_OPERATORS {
        if strsim::levenshtein(name, cand) <= 1 {
            return Some(cand);
        }
    }
    None
}
