use regex::Regex;

#[derive(Clone, Debug)]
pub enum Filter {
    All,
    Keyword(String),
    Exact(String),
    And(Vec<Filter>),
    Or(Box<Filter>, Box<Filter>),
    Not(Box<Filter>),
}

pub enum CompiledFilter {
    All,
    Regex(Regex),
    Exact(String),
    And(Vec<CompiledFilter>),
    Or(Box<CompiledFilter>, Box<CompiledFilter>),
    Not(Box<CompiledFilter>),
}

impl Filter {
    fn is_match_all(&self) -> bool {
        match self {
            Filter::All => true,
            Filter::Exact(s) => s.is_empty(),
            Filter::Keyword(k) => k.chars().all(|c| c == '*'),
            _ => false,
        }
    }

    pub fn compile(&self) -> CompiledFilter {
        match self {
            Filter::All => CompiledFilter::All,
            Filter::Keyword(k) => {
                let mut re = String::from("(?i)");
                for (i, part) in k.split('*').enumerate() {
                    if i > 0 {
                        re.push_str(".*");
                    }
                    re.push_str(&regex::escape(part));
                }
                CompiledFilter::Regex(Regex::new(&re).unwrap())
            }
            Filter::Exact(s) => CompiledFilter::Exact(s.clone()),
            Filter::And(fs) => CompiledFilter::And(fs.iter().map(|f| f.compile()).collect()),
            Filter::Or(a, b) => CompiledFilter::Or(Box::new(a.compile()), Box::new(b.compile())),
            Filter::Not(inner) => {
                if inner.is_match_all() {
                    CompiledFilter::All
                } else {
                    CompiledFilter::Not(Box::new(inner.compile()))
                }
            }
        }
    }
}

impl CompiledFilter {
    pub fn matches(&self, line: &str) -> bool {
        match self {
            CompiledFilter::All => true,
            CompiledFilter::Regex(re) => re.is_match(line),
            CompiledFilter::Exact(s) => line.contains(s.as_str()),
            CompiledFilter::And(fs) => fs.iter().all(|f| f.matches(line)),
            CompiledFilter::Or(a, b) => a.matches(line) || b.matches(line),
            CompiledFilter::Not(f) => !f.matches(line),
        }
    }
}
