//! Minimal re-implementation of the `strfmt` crate behaviour for string values.

use std::collections::HashMap;

#[derive(Debug)]
pub enum FmtError {
    Invalid(String),
    TypeError(String),
}

impl std::fmt::Display for FmtError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            FmtError::Invalid(s) => write!(f, "Invalid({})", s),
            FmtError::TypeError(s) => write!(f, "TypeError({})", s),
        }
    }
}

#[derive(PartialEq, Clone, Copy)]
enum Align {
    Left,
    Right,
    Center,
    Unspecified,
}

fn pad(s: &str, width: usize, align: Align, fill: char) -> String {
    let len = s.chars().count();
    if width <= len {
        return s.to_string();
    }
    let diff = width - len;
    match align {
        Align::Left | Align::Unspecified => format!("{}{}", s, fill.to_string().repeat(diff)),
        Align::Right => format!("{}{}", fill.to_string().repeat(diff), s),
        Align::Center => {
            let left = diff / 2;
            let right = diff - left;
            format!("{}{}{}", fill.to_string().repeat(left), s, fill.to_string().repeat(right))
        }
    }
}

