use crate::ops::Table;
use crate::record::Record;
use crate::strfmt;
use crate::value::Value;
use std::collections::HashMap;
use std::io::Write;
use unicode_width::UnicodeWidthStr;

#[derive(Clone, Debug)]
pub enum OutputMode {
    Legacy,
    Json,
    Logfmt,
    Format(String),
}

pub struct Renderer {
    pub mode: OutputMode,
    pub is_tty: bool,
    pub term_width: usize,
    pub term_height: usize,
    widths: HashMap<String, usize>,
    last_lines: usize,
    out: std::io::Stdout,
}

const PADDING: usize = 8;

fn dw(s: &str) -> usize {
    UnicodeWidthStr::width(s)
}

fn pad_to(s: &str, width: usize) -> String {
    let n = s.chars().count();
    if n >= width {
        s.to_string()
    } else {
        format!("{}{}", s, " ".repeat(width - n))
    }
}

impl Renderer {
    pub fn new(mode: OutputMode, is_tty: bool, term_width: usize, term_height: usize) -> Renderer {
        Renderer { mode, is_tty, term_width, term_height, widths: HashMap::new(), last_lines: 0, out: std::io::stdout() }
    }

    fn write_line(&mut self, s: &str) {
        let _ = writeln!(self.out, "{}", s);
    }

    pub fn flush(&mut self) {
        let _ = self.out.flush();
    }

    // -------------------------------------------------------------------
    // Records

    pub fn render_record(&mut self, rec: &Record) {
        match &self.mode {
            OutputMode::Legacy => {
                let line = self.legacy_record(rec);
                self.write_line(&line);
            }
            OutputMode::Json => {
                let line = json_record(rec);
                self.write_line(&line);
            }
            OutputMode::Logfmt => {
                let line = logfmt_record(rec);
                self.write_line(&line);
            }
            OutputMode::Format(t) => {
                let t = t.clone();
                match format_record(&t, rec) {
                    Ok(line) => self.write_line(&line),
                    Err(e) => {
                        eprintln!("Error: {}", e);
                        std::process::exit(1);
                    }
                }
            }
        }
    }

    fn legacy_record(&mut self, rec: &Record) -> String {
        if rec.fields.is_empty() {
            return rec.raw.clone();
        }
        let mut pieces: Vec<(String, usize)> = Vec::new();
        for (k, v) in &rec.fields {
            let s = format!("[{}={}]", k, v);
            let w = self.widths.entry(k.clone()).or_insert_with(|| format!("[{}={}]", k, k).len());
            if dw(&s) > *w {
                *w = s.len();
            }
            pieces.push((s, *w + PADDING));
        }
        let n = pieces.len();
        let mut line = String::new();
        for (i, (s, w)) in pieces.iter().enumerate() {
            if i + 1 == n {
                line.push_str(s);
            } else {
                line.push_str(&pad_to(s, *w));
            }
        }
        if self.is_tty && dw(&line) > self.term_width {
            let mut compact = String::new();
            for (s, _) in &pieces {
                compact.push_str(s);
            }
            return compact;
        }
        line
    }

    // -------------------------------------------------------------------
    // Tables

    fn clear_previous(&mut self) {
        let mut s = String::new();
        for _ in 0..self.last_lines {
            s.push_str("\x1b[2K\x1b[1A");
        }
        let _ = write!(self.out, "{}", s);
        self.last_lines = 0;
    }

    /// Render an aggregate table. `final_render` is true for the last render.
    pub fn render_table(&mut self, table: &Table, final_render: bool) {
        match &self.mode {
            OutputMode::Legacy => {
                let lines = self.legacy_table_lines(table);
                if self.is_tty {
                    self.clear_previous();
                }
                for l in &lines {
                    self.write_line(l);
                }
                self.last_lines = lines.len();
                self.flush();
            }
            OutputMode::Json => {
                let line = json_table(table);
                if self.is_tty {
                    self.clear_previous();
                }
                self.write_line(&line);
                self.last_lines = 1;
                self.flush();
            }
            OutputMode::Logfmt | OutputMode::Format(_) => {
                if !final_render {
                    let _ = write!(self.out, "data will be output once the computation is complete...");
                    self.flush();
                    return;
                }
                let mode = self.mode.clone();
                for row in &table.rows {
                    let rec = Table::row_to_record(row);
                    match &mode {
                        OutputMode::Logfmt => {
                            let l = logfmt_record(&rec);
                            self.write_line(&l);
                        }
                        OutputMode::Format(t) => match format_record(t, &rec) {
                            Ok(l) => self.write_line(&l),
                            Err(e) => {
                                eprintln!("Error: {}", e);
                                std::process::exit(1);
                            }
                        },
                        _ => {}
                    }
                }
                self.flush();
            }
        }
    }

    fn legacy_table_lines(&self, table: &Table) -> Vec<String> {
        if table.rows.is_empty() {
            return vec!["No data".to_string()];
        }
        let ncols = table.columns.len();
        // compute widths
        let mut widths: Vec<usize> = Vec::with_capacity(ncols);
        let mut cells: Vec<Vec<String>> = Vec::with_capacity(table.rows.len());
        for col in &table.columns {
            widths.push(col.len());
        }
        for row in &table.rows {
            let mut r = Vec::with_capacity(ncols);
            for (ci, col) in table.columns.iter().enumerate() {
                let s = match row.get(col) {
                    Some(v) => format!("{}", v),
                    None => format!("{}", Value::None),
                };
                if dw(&s) > widths[ci] {
                    widths[ci] = s.len();
                }
                r.push(s);
            }
            cells.push(r);
        }
        let mut widths: Vec<usize> = widths.iter().map(|w| w + PADDING).collect();
        let mut max_content: Vec<Option<usize>> = vec![None; ncols];
        let mut rows_limit = cells.len();
        if self.is_tty {
            let total: usize = widths.iter().sum();
            if total > self.term_width && ncols > 0 {
                let cap = self.term_width / ncols;
                for (ci, w) in widths.iter_mut().enumerate() {
                    if *w > cap {
                        let hdr = table.columns[ci].len();
                        let newv = cap.max(hdr).max(3);
                        *w = newv;
                        max_content[ci] = Some(newv.saturating_sub(1).max(if hdr > 0 { hdr } else { 1 }));
                    }
                }
            }
            if self.term_height > 3 {
                rows_limit = rows_limit.min(self.term_height - 3);
            } else {
                rows_limit = 0;
            }
        }
        let fit = |s: &str, ci: usize| -> String {
            match max_content[ci] {
                Some(m) if s.chars().count() > m => {
                    let mut t: String = s.chars().take(m.saturating_sub(1)).collect();
                    t.push('…');
                    t
                }
                _ => s.to_string(),
            }
        };
        let mut lines = Vec::new();
        let mut header = String::new();
        for (ci, col) in table.columns.iter().enumerate() {
            if ci + 1 == ncols {
                header.push_str(col);
            } else {
                header.push_str(&pad_to(col, widths[ci]));
            }
        }
        lines.push(header);
        let total: usize = widths.iter().sum();
        let dash_len = if self.is_tty { total.min(self.term_width.max(1)) } else { total };
        lines.push("-".repeat(dash_len));
        if self.is_tty && self.term_height <= 2 {
            lines.truncate(self.term_height.saturating_sub(1).max(1));
            if self.term_height <= 1 {
                return vec![String::new()];
            }
            return lines;
        }
        for row in cells.iter().take(rows_limit) {
            let mut line = String::new();
            for (ci, cell) in row.iter().enumerate() {
                let c = fit(cell, ci);
                if ci + 1 == ncols {
                    line.push_str(&c);
                } else {
                    line.push_str(&pad_to(&c, widths[ci]));
                }
            }
            lines.push(line);
        }
        lines
    }
}

pub fn json_record(rec: &Record) -> String {
    let mut m = serde_json::Map::new();
    for (k, v) in &rec.fields {
        m.insert(k.clone(), v.to_json());
    }
    serde_json::Value::Object(m).to_string()
}

pub fn json_table(table: &Table) -> String {
    let mut out = String::from("[");
    for (ri, row) in table.rows.iter().enumerate() {
        if ri > 0 {
            out.push(',');
        }
        out.push('{');
        for (ci, col) in table.columns.iter().enumerate() {
            if ci > 0 {
                out.push(',');
            }
            let v = Table::get(row, col);
            out.push_str(&serde_json::Value::String(col.clone()).to_string());
            out.push(':');
            out.push_str(&v.to_json().to_string());
        }
        out.push('}');
    }
    out.push(']');
    out
}

pub fn logfmt_record(rec: &Record) -> String {
    rec.fields.iter().map(|(k, v)| format!("{}={}", k, v)).collect::<Vec<_>>().join(" ")
}

pub fn format_record(template: &str, rec: &Record) -> Result<String, strfmt::FmtError> {
    let mut vars = HashMap::new();
    for (k, v) in &rec.fields {
        vars.insert(k.clone(), format!("{}", v));
    }
    strfmt::strfmt(template, &vars)
}
EOF
