fn is_word(c: char) -> bool {
    c.is_alphabetic()
}
fn is_num(c: char) -> bool {
    c.is_ascii_digit()
}

/// dateutil's _timelex
fn tokenize(s: &str) -> Vec<String> {
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    let mut tokens: Vec<String> = Vec::new();
    while i < chars.len() {
        let mut token = String::new();
        let mut state = 0; // 0 none, 1 'a', 2 '0', 3 'a.', 4 '0.'
        let mut seenletters = false;
        loop {
            if i >= chars.len() {
                break;
            }
            let c = chars[i];
            match state {
                0 => {
                    token.push(c);
                    i += 1;
                    if is_word(c) {
                        state = 1;
                    } else if is_num(c) {
                        state = 2;
                    } else if c.is_whitespace() {
                        token = " ".to_string();
                        break;
                    } else {
                        break;
                    }
                }
                1 => {
                    seenletters = true;
                    if is_word(c) {
                        token.push(c);
                        i += 1;
                    } else if c == '.' {
                        token.push(c);
                        i += 1;
                        state = 3;
                    } else {
                        break;
                    }
                }
                2 => {
                    if is_num(c) {
                        token.push(c);
                        i += 1;
                    } else if c == '.' || (c == ',' && token.len() >= 2) {
                        token.push(c);
                        i += 1;
                        state = 4;
                    } else {
                        break;
                    }
                }
                3 => {
                    seenletters = true;
                    if c == '.' || is_word(c) {
                        token.push(c);
                        i += 1;
                    } else if is_num(c) && token.ends_with('.') {
                        token.push(c);
                        i += 1;
                        state = 4;
                    } else {
                        break;
                    }
                }
                _ => {
                    if c == '.' || is_num(c) {
                        token.push(c);
                        i += 1;
                    } else if is_word(c) && token.ends_with('.') {
                        token.push(c);
                        i += 1;
                        state = 3;
                    } else {
                        break;
                    }
                }
            }
        }
        if (state == 3 || state == 4)
            && (seenletters || token.matches('.').count() > 1 || token.ends_with('.') || token.ends_with(','))
        {
            // split on '.' keeping the separators as tokens
            let mut parts: Vec<String> = Vec::new();
            let mut cur = String::new();
            for c in token.chars() {
                if c == '.' || c == ',' {
                    parts.push(std::mem::take(&mut cur));
                    parts.push(c.to_string());
                } else {
                    cur.push(c);
                }
            }
            parts.push(cur);
            let mut it = parts.into_iter();
            let first = it.next().unwrap_or_default();
            let mut queued: Vec<String> = it.filter(|t| !t.is_empty()).collect();
            tokens.push(first);
            tokens.append(&mut queued);
            continue;
        }
        if state == 4 && !token.contains('.') {
            token = token.replace(',', ".");
        }
        tokens.push(token);
    }
    tokens
}

fn month_of(s: &str) -> Option<u32> {
    let l = s.to_lowercase();
    for (i, (a, b)) in MONTHS.iter().enumerate() {
        if l == *a || l == *b {
            return Some(i as u32 + 1);
        }
    }
    None
}
