//! A port of the essential parts of python-dateutil's generic date parser
//! (as exposed by the `dtparse` crate) sufficient for `parseDate()`.

use chrono::{DateTime, Datelike, Local, NaiveDate, NaiveDateTime, NaiveTime, TimeZone, Utc, Weekday};

const JUMP: &[&str] =
    &[" ", ".", ",", ";", "-", "/", "'", "at", "on", "and", "ad", "m", "t", "of", "st", "nd", "rd", "th"];
const WEEKDAYS: &[(&str, &str)] = &[
    ("mon", "monday"),
    ("tue", "tuesday"),
    ("wed", "wednesday"),
    ("thu", "thursday"),
    ("fri", "friday"),
    ("sat", "saturday"),
    ("sun", "sunday"),
];
const MONTHS: &[(&str, &str)] = &[
    ("jan", "january"),
    ("feb", "february"),
    ("mar", "march"),
    ("apr", "april"),
    ("may", "may"),
    ("jun", "june"),
    ("jul", "july"),
    ("aug", "august"),
    ("sep", "september"),
    ("oct", "october"),
    ("nov", "november"),
    ("dec", "december"),
];
const UTCZONE: &[&str] = &["UTC", "GMT", "Z", "z"];

fn is_word(c: char) -> bool {
    c.is_alphabetic()
}
fn is_num(c: char) -> bool {
    c.is_ascii_digit()
}

/// dateutil's _timelex
fn tokenize(s: &str) -> Vec<String> {
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    let mut tokens: Vec<String> = Vec::new();
    while i < chars.len() {
        let mut token = String::new();
        let mut state = 0; // 0 none, 1 'a', 2 '0', 3 'a.', 4 '0.'
        let mut seenletters = false;
        loop {
            if i >= chars.len() {
                break;
            }
            let c = chars[i];
            match state {
                0 => {
                    token.push(c);
                    i += 1;
                    if is_word(c) {
                        state = 1;
                    } else if is_num(c) {
                        state = 2;
                    } else if c.is_whitespace() {
                        token = " ".to_string();
                        break;
                    } else {
                        break;
                    }
                }
                1 => {
                    seenletters = true;
                    if is_word(c) {
                        token.push(c);
                        i += 1;
                    } else if c == '.' {
                        token.push(c);
                        i += 1;
                        state = 3;
                    } else {
                        break;
                    }
                }
                2 => {
                    if is_num(c) {
                        token.push(c);
                        i += 1;
                    } else if c == '.' || (c == ',' && token.len() >= 2) {
                        token.push(c);
                        i += 1;
                        state = 4;
                    } else {
                        break;
                    }
                }
                3 => {
                    seenletters = true;
                    if c == '.' || is_word(c) {
                        token.push(c);
                        i += 1;
                    } else if is_num(c) && token.ends_with('.') {
                        token.push(c);
                        i += 1;
                        state = 4;
                    } else {
                        break;
                    }
                }
                _ => {
                    if c == '.' || is_num(c) {
                        token.push(c);
                        i += 1;
                    } else if is_word(c) && token.ends_with('.') {
                        token.push(c);
                        i += 1;
                        state = 3;
                    } else {
                        break;
                    }
                }
            }
        }
        if (state == 3 || state == 4)
            && (seenletters || token.matches('.').count() > 1 || token.ends_with('.') || token.ends_with(','))
        {
            // split on '.' keeping the separators as tokens
            let mut parts: Vec<String> = Vec::new();
            let mut cur = String::new();
            for c in token.chars() {
                if c == '.' || c == ',' {
                    parts.push(std::mem::take(&mut cur));
                    parts.push(c.to_string());
                } else {
                    cur.push(c);
                }
            }
            parts.push(cur);
            let mut it = parts.into_iter();
            let first = it.next().unwrap_or_default();
            let mut queued: Vec<String> = it.filter(|t| !t.is_empty()).collect();
            tokens.push(first);
            tokens.append(&mut queued);
            continue;
        }
        if state == 4 && !token.contains('.') {
            token = token.replace(',', ".");
        }
        tokens.push(token);
    }
    tokens
}

fn month_of(s: &str) -> Option<u32> {
    let l = s.to_lowercase();
    for (i, (a, b)) in MONTHS.iter().enumerate() {
        if l == *a || l == *b {
            return Some(i as u32 + 1);
        }
    }
    None
}
fn weekday_of(s: &str) -> Option<u32> {
    let l = s.to_lowercase();
    for (i, (a, b)) in WEEKDAYS.iter().enumerate() {
        if l == *a || l == *b {
            return Some(i as u32);
        }
    }
    None
}
fn hms_of(s: &str) -> Option<u32> {
    match s.to_lowercase().as_str() {
        "h" | "hour" | "hours" => Some(0),
        "m" | "minute" | "minutes" => Some(1),
        "s" | "second" | "seconds" => Some(2),
        _ => None,
    }
}
fn ampm_of(s: &str) -> Option<u32> {
    match s.to_lowercase().as_str() {
        "am" | "a" => Some(0),
        "pm" | "p" => Some(1),
        _ => None,
    }
}
fn is_jump(s: &str) -> bool {
    let l = s.to_lowercase();
    JUMP.iter().any(|j| *j == l)
}
fn is_pertain(s: &str) -> bool {
    s.to_lowercase() == "of"
}
fn is_utczone(s: &str) -> bool {
    UTCZONE.contains(&s)
}

#[derive(Default)]
struct Res {
    year: Option<i32>,
    month: Option<u32>,
    day: Option<u32>,
    weekday: Option<u32>,
    hour: Option<u32>,
    minute: Option<u32>,
    second: Option<u32>,
    microsecond: Option<u32>,
    tzname: Option<String>,
    tzoffset: Option<i32>,
    ampm: Option<u32>,
    century_specified: bool,
}

impl Res {
    fn len(&self) -> usize {
        let mut n = 0;
        if self.year.is_some() {
            n += 1
        }
        if self.month.is_some() {
            n += 1
        }
        if self.day.is_some() {
            n += 1
        }
        if self.weekday.is_some() {
            n += 1
        }
        if self.hour.is_some() {
            n += 1
        }
        if self.minute.is_some() {
            n += 1
        }
        if self.second.is_some() {
            n += 1
        }
        if self.microsecond.is_some() {
            n += 1
        }
        if self.tzname.is_some() {
            n += 1
        }
        if self.tzoffset.is_some() {
            n += 1
        }
        n
    }
}

#[derive(Default)]
struct Ymd {
    vals: Vec<i64>,
    century_specified: bool,
    mstridx: Option<usize>,
    dstridx: Option<usize>,
    ystridx: Option<usize>,
}

fn days_in_month(year: i32, month: u32) -> u32 {
    let (ny, nm) = if month == 12 { (year + 1, 1) } else { (year, month + 1) };
    let first_next = NaiveDate::from_ymd_opt(ny, nm, 1);
    let first = NaiveDate::from_ymd_opt(year, month, 1);
    match (first, first_next) {
        (Some(a), Some(b)) => b.signed_duration_since(a).num_days() as u32,
        _ => 31,
    }
}

impl Ymd {
    fn has_year(&self) -> bool {
        self.ystridx.is_some()
    }
    fn has_month(&self) -> bool {
        self.mstridx.is_some()
    }
    fn has_day(&self) -> bool {
        self.dstridx.is_some()
    }
    fn could_be_day(&self, value: i64) -> bool {
        if self.has_day() {
            false
        } else if !self.has_month() {
            (1..=31).contains(&value)
        } else if !self.has_year() {
            let month = self.vals[self.mstridx.unwrap()] as u32;
            value >= 1 && value <= days_in_month(2000, month.clamp(1, 12)) as i64
        } else {
            let month = self.vals[self.mstridx.unwrap()] as u32;
            let year = self.vals[self.ystridx.unwrap()] as i32;
            value >= 1 && value <= days_in_month(year, month.clamp(1, 12)) as i64
        }
    }
    fn append_str(&mut self, val: &str, label: Option<char>) -> Result<(), String> {
        let mut label = label;
        let is_digits = !val.is_empty() && val.chars().all(|c| c.is_ascii_digit());
        if is_digits && val.len() > 2 {
            self.century_specified = true;
            if label.is_some() && label != Some('Y') {
                return Err("Invalid date range given".to_string());
            }
            label = Some('Y');
        }
        let v: i64 = match val.parse::<f64>() {
            Ok(f) => f as i64,
            Err(_) => return Err("Invalid date range given".to_string()),
        };
        self.push(v, label)
    }
    fn append_num(&mut self, val: i64, label: Option<char>) -> Result<(), String> {
        let mut label = label;
        if val > 100 {
            self.century_specified = true;
            if label.is_some() && label != Some('Y') {
                return Err("Invalid date range given".to_string());
            }
            label = Some('Y');
        }
        self.push(val, label)
    }
    fn push(&mut self, v: i64, label: Option<char>) -> Result<(), String> {
        self.vals.push(v);
        let idx = self.vals.len() - 1;
        match label {
            Some('M') => {
                if self.has_month() {
                    return Err("Month is already set".to_string());
                }
                self.mstridx = Some(idx);
            }
            Some('D') => {
                if self.has_day() {
                    return Err("Day is already set".to_string());
                }
                self.dstridx = Some(idx);
            }
            Some('Y') => {
                if self.has_year() {
                    return Err("Year is already set".to_string());
                }
                self.ystridx = Some(idx);
            }
            _ => {}
        }
        Ok(())
    }

    fn resolve(&self) -> Result<(Option<i64>, Option<i64>, Option<i64>), String> {
        let len_ymd = self.vals.len();
        let mut year = None;
        let mut month = None;
        let mut day = None;
        let mut strids: Vec<(char, usize)> = Vec::new();
        if let Some(i) = self.ystridx {
            strids.push(('y', i));
        }
        if let Some(i) = self.mstridx {
            strids.push(('m', i));
        }
        if let Some(i) = self.dstridx {
            strids.push(('d', i));
        }
        if (len_ymd == strids.len() && !strids.is_empty()) || (len_ymd == 3 && strids.len() == 2) {
            // resolve from string indexes
            let mut used = vec![false; len_ymd];
            for (k, i) in &strids {
                used[*i] = true;
                match k {
                    'y' => year = Some(self.vals[*i]),
                    'm' => month = Some(self.vals[*i]),
                    _ => day = Some(self.vals[*i]),
                }
            }
            if len_ymd == 3 && strids.len() == 2 {
                let missing = used.iter().position(|u| !u).unwrap();
                if year.is_none() {
                    year = Some(self.vals[missing]);
                } else if month.is_none() {
                    month = Some(self.vals[missing]);
                } else {
                    day = Some(self.vals[missing]);
                }
            }
            return Ok((year, month, day));
        }
        let v = &self.vals;
        let mstridx = self.mstridx;
        if len_ymd > 3 {
            return Err("More than three YMD values".to_string());
        } else if len_ymd == 1 || (mstridx.is_some() && len_ymd == 2) {
            let other;
            if let Some(mi) = mstridx {
                month = Some(v[mi]);
                other = if len_ymd == 2 { Some(v[1 - mi]) } else { None };
            } else {
                other = Some(v[0]);
            }
            if len_ymd > 1 || mstridx.is_none() {
                if let Some(o) = other {
                    if o > 31 {
                        year = Some(o);
                    } else {
                        day = Some(o);
                    }
                }
            }
        } else if len_ymd == 2 {
            if v[0] > 31 {
                year = Some(v[0]);
                month = Some(v[1]);
            } else if v[1] > 31 {
                month = Some(v[0]);
                year = Some(v[1]);
            } else {
                month = Some(v[0]);
                day = Some(v[1]);
            }
        } else if len_ymd == 3 {
            match mstridx {
                Some(0) => {
                    if v[1] > 31 {
                        month = Some(v[0]);
                        year = Some(v[1]);
                        day = Some(v[2]);
                    } else {
                        month = Some(v[0]);
                        day = Some(v[1]);
                        year = Some(v[2]);
                    }
                }
                Some(1) => {
                    if v[0] > 31 {
                        year = Some(v[0]);
                        month = Some(v[1]);
                        day = Some(v[2]);
                    } else {
                        day = Some(v[0]);
                        month = Some(v[1]);
                        year = Some(v[2]);
                    }
                }
                Some(_) => {
                    if v[1] > 31 {
                        day = Some(v[0]);
                        year = Some(v[1]);
                        month = Some(v[2]);
                    } else {
                        year = Some(v[0]);
                        day = Some(v[1]);
                        month = Some(v[2]);
                    }
                }
                None => {
                    if v[0] > 31 || self.ystridx == Some(0) {
                        year = Some(v[0]);
                        month = Some(v[1]);
                        day = Some(v[2]);
                    } else if v[0] > 12 {
                        day = Some(v[0]);
                        month = Some(v[1]);
                        year = Some(v[2]);
                    } else {
                        month = Some(v[0]);
                        day = Some(v[1]);
                        year = Some(v[2]);
                    }
                }
            }
        }
        Ok((year, month, day))
    }
}

fn parse_ms(s: &str) -> Result<(u32, u32), String> {
    if !s.contains('.') {
        return s.parse::<u32>().map(|v| (v, 0)).map_err(|_| "Invalid date range given".to_string());
    }
    let mut parts = s.splitn(2, '.');
    let i = parts.next().unwrap_or("0");
    let f = parts.next().unwrap_or("0");
    let sec: u32 = i.parse().map_err(|_| "Invalid date range given".to_string())?;
    let mut frac = f.to_string();
    while frac.len() < 6 {
        frac.push('0');
    }
    let us: u32 = frac[..6].parse().map_err(|_| "Invalid date range given".to_string())?;
    Ok((sec, us))
}

fn parse_min_sec(value: f64) -> (u32, Option<u32>) {
    let minute = value as u32;
    let rem = value - value.floor();
    if rem != 0.0 {
        (minute, Some((rem * 60.0) as u32))
    } else {
        (minute, None)
    }
}

fn to_f64(s: &str) -> Option<f64> {
    if s.is_empty() {
        return None;
    }
    // python float(): allow leading/trailing whitespace, digits, '.', exponent
    let t = s.trim();
    if t.chars().all(|c| c.is_ascii_digit() || c == '.') && t.chars().any(|c| c.is_ascii_digit()) {
        return t.parse::<f64>().ok();
    }
    None
}

fn adjust_ampm(hour: u32, ampm: u32) -> u32 {
    if hour < 12 && ampm == 1 {
        hour + 12
    } else if hour == 12 && ampm == 0 {
        0
    } else {
        hour
    }
}

fn could_be_tzname(res: &Res, token: &str) -> bool {
    res.hour.is_some()
        && res.tzname.is_none()
        && res.tzoffset.is_none()
        && token.len() <= 5
        && (token.chars().all(|c| c.is_ascii_uppercase()) || is_utczone(token))
}

fn find_hms_idx(idx: usize, tokens: &[String]) -> Option<usize> {
    let len_l = tokens.len();
    if idx + 1 < len_l && hms_of(&tokens[idx + 1]).is_some() {
        Some(idx + 1)
    } else if idx + 2 < len_l && tokens[idx + 1] == " " && hms_of(&tokens[idx + 2]).is_some() {
        Some(idx + 2)
    } else if idx > 0 && hms_of(&tokens[idx - 1]).is_some() {
        Some(idx - 1)
    } else if idx > 1 && tokens[idx - 1] == " " && hms_of(&tokens[idx - 2]).is_some() {
        Some(idx - 2)
    } else {
        None
    }
}

fn assign_hms(res: &mut Res, value_repr: &str, hms: u32) -> Result<(), String> {
    let value: f64 = to_f64(value_repr).unwrap_or(0.0);
    match hms {
        0 => {
            res.hour = Some(value as u32);
            let rem = value - value.floor();
            if rem != 0.0 {
                res.minute = Some((rem * 60.0) as u32);
            }
        }
        1 => {
            let (m, s) = parse_min_sec(value);
            res.minute = Some(m);
            if let Some(s) = s {
                res.second = Some(s);
            }
        }
        _ => {
            let (s, us) = parse_ms(value_repr)?;
            res.second = Some(s);
            res.microsecond = Some(us);
        }
    }
    Ok(())
}

fn parse_numeric_token(tokens: &[String], mut idx: usize, ymd: &mut Ymd, res: &mut Res) -> Result<usize, String> {
    let token = &tokens[idx];
    let value_repr = token.clone();
    let value = to_f64(token).unwrap_or(0.0);
    let len_li = token.len();
    let len_l = tokens.len();
    let next_is_not_time = idx + 1 >= len_l || (tokens[idx + 1] != ":" && hms_of(&tokens[idx + 1]).is_none());
    if ymd.vals.len() == 3 && (len_li == 2 || len_li == 4) && res.hour.is_none() && next_is_not_time {
        // 19990101T23[59]
        res.hour = Some(token[..2].parse().unwrap_or(0));
        if len_li == 4 {
            res.minute = Some(token[2..].parse().unwrap_or(0));
        }
    } else if len_li == 6 || (len_li > 6 && token.find('.') == Some(6)) {
        if ymd.vals.is_empty() && !token.contains('.') {
            ymd.append_str(&token[..2], None)?;
            ymd.append_str(&token[2..4], None)?;
            ymd.append_str(&token[4..], None)?;
        } else {
            res.hour = Some(token[..2].parse().unwrap_or(0));
            res.minute = Some(token[2..4].parse().unwrap_or(0));
            let (s, us) = parse_ms(&token[4..])?;
            res.second = Some(s);
            res.microsecond = Some(us);
        }
    } else if len_li == 8 || len_li == 12 || len_li == 14 {
        ymd.append_str(&token[..4], Some('Y'))?;
        ymd.append_str(&token[4..6], None)?;
        ymd.append_str(&token[6..8], None)?;
        if len_li > 8 {
            res.hour = Some(token[8..10].parse().unwrap_or(0));
            res.minute = Some(token[10..12].parse().unwrap_or(0));
            if len_li > 12 {
                res.second = Some(token[12..].parse().unwrap_or(0));
            }
        }
    } else if let Some(hms_idx) = find_hms_idx(idx, tokens) {
        // HH[ ]h or MM[ ]m or SS[.ss][ ]s
        let hms = hms_of(&tokens[hms_idx]).unwrap();
        if hms_idx > idx {
            idx = hms_idx;
            assign_hms(res, &value_repr, hms)?;
        } else {
            // hms before the value: e.g. "h 10"? Use next unit
            assign_hms(res, &value_repr, hms + 1)?;
        }
    } else if idx + 2 < len_l && tokens[idx + 1] == ":" {
        res.hour = Some(value as u32);
        let v2 = to_f64(&tokens[idx + 2].replace(',', ".")).ok_or_else(|| "Invalid date range given".to_string())?;
        let (m, s) = parse_min_sec(v2);
        res.minute = Some(m);
        if let Some(s) = s {
            res.second = Some(s);
        }
        if idx + 4 < len_l && tokens[idx + 3] == ":" {
            let (s, us) = parse_ms(&tokens[idx + 4])?;
            res.second = Some(s);
            res.microsecond = Some(us);
            idx += 2;
        }
        idx += 2;
    } else if idx + 1 < len_l && (tokens[idx + 1] == "-" || tokens[idx + 1] == "/" || tokens[idx + 1] == ".") {
        let sep = tokens[idx + 1].clone();
        ymd.append_str(&value_repr, None)?;
        if idx + 2 < len_l && !is_jump(&tokens[idx + 2]) {
            if tokens[idx + 2].chars().all(|c| c.is_ascii_digit()) {
                ymd.append_str(&tokens[idx + 2], None)?;
            } else {
                match month_of(&tokens[idx + 2]) {
                    Some(m) => ymd.append_num(m as i64, Some('M'))?,
                    None => return Err(format!("UnrecognizedToken({:?})", tokens[idx + 2])),
                }
            }
            if idx + 3 < len_l && tokens[idx + 3] == sep {
                if idx + 4 < len_l {
                    match month_of(&tokens[idx + 4]) {
                        Some(m) => ymd.append_num(m as i64, Some('M'))?,
                        None => ymd.append_str(&tokens[idx + 4], None)?,
                    }
                }
                idx += 2;
            }
            idx += 1;
        }
        idx += 1;
    } else if idx + 1 >= len_l || is_jump(&tokens[idx + 1]) {
        if idx + 2 < len_l && ampm_of(&tokens[idx + 2]).is_some() {
            let hour = value as u32;
            res.hour = Some(adjust_ampm(hour, ampm_of(&tokens[idx + 2]).unwrap()));
            idx += 1;
        } else {
            ymd.append_str(&value_repr, None)?;
        }
        idx += 1;
    } else if ampm_of(&tokens[idx + 1]).is_some() && (0.0..24.0).contains(&value) {
        let hour = value as u32;
        res.hour = Some(adjust_ampm(hour, ampm_of(&tokens[idx + 1]).unwrap()));
        idx += 1;
    } else if ymd.could_be_day(value as i64) {
        ymd.append_num(value as i64, None)?;
    } else {
        return Err(format!("UnrecognizedToken({:?})", token));
    }
    Ok(idx)
}

fn convert_year(year: i64, century_specified: bool) -> i64 {
    let now_year = Local::now().year() as i64;
    let century = (now_year / 100) * 100;
    let mut year = year;
    if year < 100 && !century_specified {
        year += century;
        if (year - now_year).abs() >= 50 {
            if year < now_year {
                year += 100;
            } else {
                year -= 100;
            }
        }
    }
    year
}

pub fn parse(s: &str) -> Result<DateTime<Utc>, String> {
    let tokens = tokenize(s);
    let mut res = Res::default();
    let mut ymd = Ymd::default();
    let len_l = tokens.len();
    let mut i = 0;
    let mut tokens = tokens;
    while i < len_l {
        let tok = tokens[i].clone();
        if to_f64(&tok).is_some() {
            i = parse_numeric_token(&tokens, i, &mut ymd, &mut res)?;
        } else if let Some(wd) = weekday_of(&tok) {
            res.weekday = Some(wd);
        } else if let Some(m) = month_of(&tok) {
            ymd.append_num(m as i64, Some('M'))?;
            if i + 1 < len_l {
                if tokens[i + 1] == "-" || tokens[i + 1] == "/" {
                    let sep = tokens[i + 1].clone();
                    if i + 2 < len_l {
                        ymd.append_str(&tokens[i + 2], None)?;
                    }
                    if i + 3 < len_l && tokens[i + 3] == sep {
                        if i + 4 < len_l {
                            ymd.append_str(&tokens[i + 4], None)?;
                        }
                        i += 2;
                    }
                    i += 2;
                } else if i + 4 < len_l && tokens[i + 1] == " " && tokens[i + 3] == " " && is_pertain(&tokens[i + 2]) {
                    if tokens[i + 4].chars().all(|c| c.is_ascii_digit()) {
                        let v: i64 = tokens[i + 4].parse().unwrap_or(0);
                        let y = convert_year(v, false);
                        ymd.append_str(&y.to_string(), Some('Y'))?;
                    }
                    i += 4;
                }
            }
        } else if let Some(ap) = ampm_of(&tok) {
            let valid = match res.hour {
                None => return Err("AmPmWithoutHour".to_string()),
                Some(h) => {
                    if res.ampm.is_some() {
                        return Err("AmPmWithoutHour".to_string());
                    }
                    if h > 12 {
                        return Err("InvalidHour".to_string());
                    }
                    true
                }
            };
            if valid {
                res.hour = Some(adjust_ampm(res.hour.unwrap(), ap));
                res.ampm = Some(ap);
            }
        } else if could_be_tzname(&res, &tok) {
            res.tzname = Some(tok.clone());
            res.tzoffset = if is_utczone(&tok) { Some(0) } else { None };
            if i + 1 < len_l && (tokens[i + 1] == "+" || tokens[i + 1] == "-") {
                tokens[i + 1] = if tokens[i + 1] == "+" { "-".to_string() } else { "+".to_string() };
                res.tzoffset = None;
                if is_utczone(&tok) {
                    res.tzname = None;
                }
            }
        } else if res.hour.is_some() && (tok == "+" || tok == "-") {
            let signal: i32 = if tok == "+" { 1 } else { -1 };
            if i + 1 >= len_l {
                return Err(format!("UnrecognizedToken({:?})", tok));
            }
            let nxt = tokens[i + 1].clone();
            let len_li = nxt.len();
            let off: i32;
            if len_li == 4 {
                off = nxt[..2].parse::<i32>().unwrap_or(0) * 3600 + nxt[2..].parse::<i32>().unwrap_or(0) * 60;
            } else if i + 2 < len_l && tokens[i + 2] == ":" {
                off = nxt.parse::<i32>().unwrap_or(0) * 3600
                    + tokens.get(i + 3).and_then(|t| t.parse::<i32>().ok()).unwrap_or(0) * 60;
                i += 2;
            } else if len_li <= 2 {
                off = nxt[..len_li.min(2)].parse::<i32>().unwrap_or(0) * 3600;
            } else {
                return Err(format!("UnrecognizedToken({:?})", nxt));
            }
            res.tzoffset = Some(off * signal);
            i += 1;
        } else if !is_jump(&tok) {
            return Err(format!("UnrecognizedToken({:?})", tok));
        }
        i += 1;
    }

    let (year, month, day) = ymd.resolve()?;
    if let Some(y) = year {
        res.year = Some(y as i32);
        res.century_specified = ymd.century_specified;
    }
    if let Some(m) = month {
        res.month = Some(m as u32);
    }
    if let Some(d) = day {
        res.day = Some(d as u32);
    }
    if res.len() == 0 {
        return Err("NoDate".to_string());
    }
    if let Some(y) = res.year {
        res.year = Some(convert_year(y as i64, res.century_specified) as i32);
    }
    // validate / tz handling
    if (res.tzoffset == Some(0) && res.tzname.is_none())
        || res.tzname.as_deref() == Some("Z")
        || res.tzname.as_deref() == Some("z")
    {
        res.tzname = Some("UTC".to_string());
        res.tzoffset = Some(0);
    } else if res.tzoffset.unwrap_or(0) != 0 && res.tzname.as_deref().map(is_utczone).unwrap_or(false) {
        res.tzoffset = Some(0);
    }

    // build naive datetime from defaults (today at midnight)
    let now = Local::now().naive_local().date();
    let year = res.year.unwrap_or(now.year());
    let month = res.month.unwrap_or(now.month());
    let mut day = res.day.unwrap_or(now.day());
    if res.day.is_none() {
        let dim = days_in_month(year, month.clamp(1, 12));
        if day > dim {
            day = dim;
        }
    }
    let date = NaiveDate::from_ymd_opt(year, month, day).ok_or_else(|| "ImpossibleTimestamp(\"Invalid date range given\")".to_string())?;
    let time = NaiveTime::from_hms_micro_opt(
        res.hour.unwrap_or(0),
        res.minute.unwrap_or(0),
        res.second.unwrap_or(0),
        res.microsecond.unwrap_or(0),
    )
    .ok_or_else(|| "ImpossibleTimestamp(\"Invalid time range given\")".to_string())?;
    let mut naive = NaiveDateTime::new(date, time);
    if let (Some(wd), None) = (res.weekday, res.day) {
        let target = match wd {
            0 => Weekday::Mon,
            1 => Weekday::Tue,
            2 => Weekday::Wed,
            3 => Weekday::Thu,
            4 => Weekday::Fri,
            5 => Weekday::Sat,
            _ => Weekday::Sun,
        };
        let cur = naive.weekday().num_days_from_monday() as i64;
        let want = target.num_days_from_monday() as i64;
        let diff = (want - cur).rem_euclid(7);
        naive += chrono::TimeDelta::days(diff);
    }
    if let Some(name) = &res.tzname {
        if res.tzoffset.is_none() && !is_utczone(name) && name != "UTC" {
            println!("tzname {} identified but not understood.", name);
        }
    }
    Ok(Utc.from_utc_datetime(&naive))
}

/// Map internal error strings to the dtparse-like display.
pub fn error_display(e: &str) -> String {
    if e.starts_with("UnrecognizedToken") || e.starts_with("ImpossibleTimestamp") || e == "NoDate" || e == "AmPmWithoutHour" || e == "InvalidHour" {
        e.to_string()
    } else {
        format!("ImpossibleTimestamp({:?})", e)
    }
}
