fn load_dir(dir: &Path, map: &mut HashMap<String, Vec<Operator>>) -> std::io::Result<()> {
    let rd = std::fs::read_dir(dir)?;
    for entry in rd {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let path = entry.path();
        if path.is_dir() {
            continue;
        }
        let content = match std::fs::read_to_string(&path) {
            Ok(c) => c,
            Err(_) => continue,
        };
        match toml::from_str::<AliasFile>(&content) {
            Ok(af) => {
                let template = af.template.trim().to_string();
                let parser = Parser::for_alias(&template);
                let ops = parser.parse_template();
                for d in parser.errors.borrow().iter() {
                    eprint!("{}", d.render(&template, "error"));
                }
                map.entry(af.keyword).or_insert(ops);
            }
            Err(e) => {
                eprintln!("warning: invalid alias: {}\n--> {}\n |\n |", e, path.display());
            }
        }
    }
    Ok(())
}

pub fn load(alias_dir: Option<&str>, no_alias: bool) -> Result<Aliases, String> {
    let mut map = HashMap::new();
    if no_alias {
        return Ok(Aliases { map });
    }
    if let Some(dir) = alias_dir {
        load_dir(Path::new(dir), &mut map).map_err(|e| e.to_string())?;
        return Ok(Aliases { map });
    }
    let mut cur: Option<PathBuf> = std::env::current_dir().ok();
    while let Some(dir) = cur {
        let candidate = dir.join(".agrind-aliases");
        if candidate.is_dir() {
            let _ = load_dir(&candidate, &mut map);
        }
        cur = dir.parent().map(|p| p.to_path_buf());
    }
    Ok(Aliases { map })
}
