fn unknown_function(op: &Operator) -> Option<String> {
    use ops::{AggFunc, InlineOp};
    match op {
        Operator::Inline(i) => match i {
            InlineOp::Json { from } | InlineOp::Logfmt { from } => from.as_ref().and_then(|e| e.unknown_function()),
            InlineOp::Parse { from, .. } | InlineOp::ParseRegex { from, .. } => {
                from.as_ref().and_then(|e| e.unknown_function())
            }
            InlineOp::Split { input, output, .. } => input
                .as_ref()
                .and_then(|e| e.unknown_function())
                .or_else(|| output.as_ref().and_then(|e| e.unknown_function())),
            InlineOp::Where(Some(e)) => e.unknown_function(),
            InlineOp::Total { expr, .. } | InlineOp::Timeslice { expr, .. } | InlineOp::FieldExpr { expr, .. } => {
                expr.unknown_function()
            }
            _ => None,
        },
        Operator::Agg(m) => {
            for (f, _) in &m.aggs {
                let e = match f {
                    AggFunc::Count(Some(e)) => Some(e),
                    AggFunc::Count(None) => None,
                    AggFunc::Sum(e) | AggFunc::Min(e) | AggFunc::Max(e) | AggFunc::Avg(e) => Some(e),
                    AggFunc::Percentile(e, _) | AggFunc::CountDistinct(e) => Some(e),
                };
                if let Some(u) = e.and_then(|e| e.unknown_function()) {
                    return Some(u);
                }
            }
            for (e, _) in &m.keys {
                if let Some(u) = e.unknown_function() {
                    return Some(u);
                }
            }
            None
        }
        Operator::Sort(s) => {
            for e in &s.exprs {
                if let Some(u) = e.unknown_function() {
                    return Some(u);
                }
            }
            None
        }
    }
}

/// Push a record through the pre-aggregate inline operators starting at `idx`.
fn push_through(pre: &mut [InlineState], idx: usize, rec: Record, out: &mut Vec<Record>) {
    if idx >= pre.len() {
        out.push(rec);
        return;
    }
    if !pre[idx].accepting() {
        return;
    }
    if let Some(r) = pre[idx].process(rec) {
        push_through(pre, idx + 1, r, out);
    }
}

fn finish_pre(pre: &mut [InlineState], out: &mut Vec<Record>) {
    for idx in 0..pre.len() {
        let buffered = pre[idx].finish();
        for r in buffered {
            push_through(pre, idx + 1, r, out);
        }
    }
}

fn run(query: parser::Query, reader: Box<dyn BufRead + Send>, mut renderer: Renderer) {
    let filter = query.filter.compile();
    let mut pre: Vec<InlineState> = Vec::new();
    let mut stages: Vec<Stage> = Vec::new();
    for op in query.operators {
        if stages.is_empty() {
            match op {
                Operator::Inline(i) => pre.push(InlineState::new(i)),
                other => stages.push(Stage::from_operator(other)),
            }
        } else {
            stages.push(Stage::from_operator(op));
        }
    }
    let has_agg = !stages.is_empty();

    let (tx, rx) = mpsc::channel::<String>();
    std::thread::spawn(move || {
        let mut reader = reader;
        let mut buf: Vec<u8> = Vec::new();
        loop {
            buf.clear();
            match reader.read_until(b'\n', &mut buf) {
                Ok(0) => break,
                Ok(_) => {
                    if buf.ends_with(b"\n") {
                        buf.pop();
                        if buf.ends_with(b"\r") {
                            buf.pop();
                        }
                    }
                    let line = String::from_utf8_lossy(&buf).into_owned();
                    if tx.send(line).is_err() {
                        break;
                    }
                }
                Err(_) => break,
            }
        }
    });

    let tick = Duration::from_millis(50);
    let mut last_render = Instant::now();
    let mut dirty = false;
    let mut out_recs: Vec<Record> = Vec::new();

    let mut handle_records = |recs: &mut Vec<Record>, stages: &mut Vec<Stage>, renderer: &mut Renderer| {
        for rec in recs.drain(..) {
            if stages.is_empty() {
                renderer.render_record(&rec);
            } else {
                match &mut stages[0] {
                    Stage::Agg(a) => a.process(&rec),
                    Stage::Sort(s) => s.process(&rec),
                    Stage::Inline(_) => {}
                }
            }
        }
    };

    loop {
        let msg = if has_agg && renderer.is_tty { rx.recv_timeout(tick) } else { rx.recv().map_err(|_| mpsc::RecvTimeoutError::Disconnected) };
        match msg {
            Ok(line) => {
                if filter.matches(&line) {
                    let rec = Record::new(line);
                    push_through(&mut pre, 0, rec, &mut out_recs);
                    if !out_recs.is_empty() {
                        handle_records(&mut out_recs, &mut stages, &mut renderer);
                        dirty = true;
                    }
                }
            }
            Err(mpsc::RecvTimeoutError::Timeout) => {}
            Err(mpsc::RecvTimeoutError::Disconnected) => break,
        }
        if has_agg && renderer.is_tty && dirty && last_render.elapsed() >= tick {
            let table = current_table(&mut stages);
            renderer.render_table(&table, false);
            last_render = Instant::now();
            dirty = false;
        }
    }
    finish_pre(&mut pre, &mut out_recs);
    if !out_recs.is_empty() {
        handle_records(&mut out_recs, &mut stages, &mut renderer);
    }
    if has_agg {
        let table = current_table(&mut stages);
        renderer.render_table(&table, true);
    }
    renderer.flush();
}

fn current_table(stages: &mut Vec<Stage>) -> ops::Table {
    let first = match &stages[0] {
        Stage::Agg(a) => a.emit(),
        Stage::Sort(s) => s.emit(),
        Stage::Inline(_) => ops::Table::default(),
    };
    ops::run_stages(&mut stages[1..], first)
}
