fn install_panic_hook() {
    std::panic::set_hook(Box::new(|info| {
        let cause = match info.payload().downcast_ref::<&str>() {
            Some(s) => s.to_string(),
            None => match info.payload().downcast_ref::<String>() {
                Some(s) => s.clone(),
                None => "Unknown".to_string(),
            },
        };
        let explanation = match info.location() {
            Some(l) => format!("Panic occurred in file '{}' at line {}", l.file(), l.line()),
            None => "Panic location unknown.".to_string(),
        };
        let name = format!("report-{}.toml", pseudo_uuid());
        let path = std::env::temp_dir().join(name);
        let report = format!(
            "name = \"ag\"\noperating_system = \"unix:Unknown\"\ncrate_version = \"0.19.6\"\nexplanation = \"\"\"\n{}\n\"\"\"\ncause = {:?}\nmethod = \"Panic\"\nbacktrace = \"\"\"\n\"\"\"\n",
            explanation, cause
        );
        let _ = std::fs::write(&path, report);
        let stderr = std::io::stderr();
        let mut e = stderr.lock();
        let _ = writeln!(e, "Well, this is embarrassing.\n");
        let _ = writeln!(e, "ag had a problem and crashed. To help us diagnose the problem you can send us a crash report.\n");
        let _ = writeln!(
            e,
            "We have generated a report file at \"{}\". Submit an issue or email with the subject of \"ag Crash Report\" and include the report as an attachment.\n",
