        );
        let _ = writeln!(e, "- Authors: Russell Cohen <russell.r.cohen@gmail.com>\n");
        let _ = writeln!(e, "We take privacy seriously, and do not perform any automated error collection. In order to improve the software, we rely on people to submit reports.\n");
        let _ = writeln!(e, "Thank you kindly!");
    }));
}

