/// Quote-aware split used by the `split` operator.
pub fn split_text(text: &str, sep: &str) -> Vec<String> {
    let mut out = Vec::new();
    if sep.is_empty() {
        return text.chars().map(|c| c.to_string()).collect();
    }
    let mut rest = text;
    while !rest.is_empty() {
        let c = rest.chars().next().unwrap();
        if c == '"' || c == '\\'' {
            if let Some(end) = rest[1..].find(c) {
                out.push(rest[1..1 + end].to_string());
                rest = &rest[1 + end + 1..];
                if let Some(r) = rest.strip_prefix(sep) {
                    rest = r;
                }
                continue;
            }
        }
        match rest.find(sep) {
            Some(idx) => {
                out.push(rest[..idx].to_string());
                rest = &rest[idx + sep.len()..];
            }
            None => {
                out.push(rest.to_string());
                rest = "";
            }
        }
    }
    out
