import math, itertools
def run(data, eps, qs, var):
    insert_threshold = int(1.0/(2.0*eps))
    samples=[]; n=0; inserts=0
    def invariant(r):
        i = int(math.floor(2.0*eps*r))
        return 1 if i < 1 else i
    def compress_fwd():
        nonlocal samples
        if len(samples) < 3: return
        s_mx = len(samples)-1
        idx=0; r=var['r0']
        while idx < s_mx:
            cur_g = samples[idx][1]; nxt = samples[idx+1]
            cond = (cur_g + nxt[1] + nxt[2] <= invariant(r)) if var['le'] else (cur_g + nxt[1] + nxt[2] < invariant(r))
            if cond:
                samples[idx][0]=nxt[0]; samples[idx][1]+=nxt[1]; samples[idx][2]=nxt[2]
                del samples[idx+1]; s_mx -= 1
                r += {'0':0,'1':1,'g':nxt[1]}[var['merge']]
            else:
                r += {'1':1,'g':cur_g}[var['adv']]
                idx += 1
    def compress_bwd():
        nonlocal samples
        if len(samples) < 3: return
        # iterate from the end: i from len-2 down to 1? compute true ranks
        i = len(samples)-2
        ranks=[0]*len(samples)
        acc=0
        for k,e in enumerate(samples):
            acc+=e[1]; ranks[k]=acc
        while i >= 1:
            cur=samples[i]; nxt=samples[i+1]
            r = ranks[i] if var['adv']=='g' else i+var['r0']
            if cur[1] + nxt[1] + nxt[2] <= invariant(r):
                cur[0]=nxt[0]; cur[1]+=nxt[1]; cur[2]=nxt[2]
                del samples[i+1]
            i -= 1
    compress = compress_bwd if var['dir']=='bwd' else compress_fwd
    for v in data:
        n += 1
        s=len(samples)
        if s==0:
            samples.insert(0,[v,1,0])
        else:
            idx=0; r=0
            for e in samples:
                if e[0] < v: idx+=1; r+=e[1]
                else: break
            delta = 0 if (idx==0 or idx==s) else invariant(r)-1
            samples.insert(idx,[v,1,delta])
        inserts = (inserts+1) % insert_threshold
        if inserts == 0: compress()
    out=[]
    for q in qs:
        s=len(samples); r=0; nphi=q*n; res=None
        for i in range(1,s):
            prev=samples[i-1]; cur=samples[i]
            r+=prev[1]
            if r+cur[1]+cur[2] > nphi+invariant(nphi)/2.0: res=prev[0]; break
        if res is None: res=samples[s-1][0]
        out.append(res)
    return out
