// CKMS streaming quantile estimator (compatible with the `quantiles` crate behaviour).
// Samples are kept in a blocked list for faster insertion while preserving flat-list semantics.

#[derive(Clone, Debug)]
struct Entry {
    v: f64,
    g: usize,
    delta: usize,
}

#[derive(Clone, Debug)]
struct Block {
    data: Vec<Entry>,
    gsum: usize,
}

const BLOCK_CAP: usize = 1024;

#[derive(Clone, Debug)]
pub struct Ckms {
    n: usize,
    error: f64,
    insert_threshold: usize,
    inserts: usize,
    blocks: Vec<Block>,
    len: usize,
}

impl Ckms {
    pub fn new(error: f64) -> Ckms {
        let t = 1.0 / (2.0 * error);
        let insert_threshold = if t < 1.0 { 1 } else { t as usize };
        Ckms { n: 0, error, insert_threshold, inserts: 0, blocks: Vec::new(), len: 0 }
    }

    fn invariant(&self, r: f64) -> usize {
        let i = (2.0 * self.error * r).floor() as usize;
        if i < 1 {
            1
        } else {
            i
        }
    }

    pub fn insert(&mut self, v: f64) {
        self.n += 1;
        if self.len == 0 {
            self.blocks.push(Block { data: vec![Entry { v, g: 1, delta: 0 }], gsum: 1 });
            self.len = 1;
        } else {
            // locate block: first block whose last value is >= v (else the last block)
            let nb = self.blocks.len();
            let mut bi = 0;
            let mut r = 0usize;
            while bi + 1 < nb && self.blocks[bi].data.last().map(|e| e.v < v).unwrap_or(true) {
                r += self.blocks[bi].gsum;
                bi += 1;
            }
            let block = &mut self.blocks[bi];
            let idx = block.data.partition_point(|e| e.v < v);
            r += block.data[..idx].iter().map(|e| e.g).sum::<usize>();
            let is_first = bi == 0 && idx == 0;
            let is_last = bi + 1 == nb && idx == block.data.len();
            let delta = if is_first || is_last { 0 } else { self.invariant(r as f64) - 1 };
            let block = &mut self.blocks[bi];
            block.data.insert(idx, Entry { v, g: 1, delta });
            block.gsum += 1;
            self.len += 1;
            if block.data.len() > BLOCK_CAP {
                let tail = block.data.split_off(BLOCK_CAP / 2);
                let tail_sum: usize = tail.iter().map(|e| e.g).sum();
                block.gsum -= tail_sum;
                self.blocks.insert(bi + 1, Block { data: tail, gsum: tail_sum });
            }
        }
        self.inserts = (self.inserts + 1) % self.insert_threshold;
        if self.inserts == 0 {
            self.compress();
        }
    }

    fn compress(&mut self) {
        if self.len < 3 {
            return;
        }
        // flat semantics: walk pairs (cur, nxt) across the whole list
        let mut r: usize = 1;
        let mut bi = 0;
        let mut idx = 0;
        loop {
            // find the position of `cur`; make sure (bi, idx) is valid
            while bi < self.blocks.len() && idx >= self.blocks[bi].data.len() {
                bi += 1;
                idx = 0;
            }
            if bi >= self.blocks.len() {
                break;
            }
            // find nxt
            let (nbi, nidx) = if idx + 1 < self.blocks[bi].data.len() {
                (bi, idx + 1)
            } else {
                let mut b = bi + 1;
                while b < self.blocks.len() && self.blocks[b].data.is_empty() {
                    b += 1;
                }
                if b >= self.blocks.len() {
                    break;
                }
                (b, 0)
            };
            // the flat algorithm stops when cur is the last element; also requires nxt not to be the
            // "last" index boundary (idx < s_mx) which is equivalent to nxt existing.
            let cur_g = self.blocks[bi].data[idx].g;
            let (nv, ng, nd) = {
                let e = &self.blocks[nbi].data[nidx];
                (e.v, e.g, e.delta)
            };
            if cur_g + ng + nd <= self.invariant(r as f64) {
                {
                    let cur = &mut self.blocks[bi].data[idx];
                    cur.v = nv;
                    cur.g += ng;
                    cur.delta = nd;
                }
                self.blocks[bi].gsum += ng;
                self.blocks[nbi].data.remove(nidx);
                self.blocks[nbi].gsum -= ng;
                self.len -= 1;
                if self.blocks[nbi].data.is_empty() {
                    self.blocks.remove(nbi);
                }
            } else {
                idx += 1;
            }
            r += 1;
        }
    }

    pub fn query(&self, q: f64) -> Option<f64> {
        if self.len == 0 {
            return None;
        }
        let mut r = 0usize;
        let nphi = q * (self.n as f64);
        let rhs = nphi + (self.invariant(nphi) as f64) / 2.0;
        let mut prev: Option<&Entry> = None;
        for e in self.blocks.iter().flat_map(|b| b.data.iter()) {
            if let Some(p) = prev {
                r += p.g;
                let lhs = (r + e.g + e.delta) as f64;
                if lhs > rhs {
                    return Some(p.v);
                }
            }
            prev = Some(e);
        }
        prev.map(|e| e.v)
    }
}
